  static final MockTest topikI = MockTest(
    examName: "TOPIK I",
    language: "ko",
    sections: const [
      MockSection(sectionId: "vocab_mc", title: "어휘 — 객관식 (Vocabulary — Multiple Choice)", count: 10),
      MockSection(sectionId: "grammar_fib", title: "문법 — 빈칸 채우기 (Grammar — Fill in the Blank)", count: 5),
      MockSection(sectionId: "reading", title: "읽기 (Reading Comprehension)", count: 5),
      MockSection(sectionId: "listening", title: "듣기 (Listening — text-based)", count: 5),
    ],
    questions: const [
      MockQuestion(id: "ko_topik1_mock_q001", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "빈칸에 알맞은 것을 고르십시오.\n\n저는 아침마다 공원에서 __________.", questionEn: "Choose the correct word: 'I ___ in the park every morning.'", correctAnswer: "운동합니다", distractors: const ["요리합니다", "청소합니다", "세수합니다"], explanation: const LocalizedText({'en': "운동합니다 means 'to exercise'. Exercising in a park every morning is a natural activity. 요리합니다 = cook, 청소합니다 = clean, 세수합니다 = wash face. Only 운동합니다 fits naturally with 공원에서 (in the park).", 'ko': "'운동합니다'는 'exercise'라는 뜻입니다. 공원에서 아침마다 운동하는 것은 자연스러운 표현입니다.", 'ja': "「운동합니다」は「運動する」という意味です。毎朝公園で運動するのは自然な行動です。「요리합니다」＝料理をする、「청소합니다」＝掃除をする、「세수합니다」＝顔を洗う。「운동합니다」だけが「공원에서（公園で）」という文脈に自然に馴染みます。", 'zh': "“운동합니다”意为“锻炼”。每天早上在公园锻炼是一种自然而然的活动。요리합니다 = 做饭，청소합니다 = 打扫，세수합니다 = 洗脸。只有“운동합니다”与“공원에서”（在公园里）搭配起来才自然。", 'zh_TW': "「운동합니다」的意思是「運動」。每天早上在公園運動是一項自然而然的活動。「요리합니다」＝煮飯、「청소합니다」＝打掃、「세수합니다」＝洗臉。只有「운동합니다」與「공원에서」（在公園）搭配起來才自然。", 'es': "«운동합니다» significa «hacer ejercicio». Hacer ejercicio en el parque cada mañana es una actividad natural. «요리합니다» = cocinar, «청소합니다» = limpiar, «세수합니다» = lavarse la cara. Solo «운동합니다» encaja de forma natural con «공원에서» (en el parque).", 'fr': "« 운동합니다 » signifie « faire de l'exercice ». Faire de l'exercice dans un parc tous les matins est une activité naturelle. « 요리합니다 » = cuisiner, « 청소합니다 » = faire le ménage, « 세수합니다 » = se laver le visage. Seul « 운동합니다 » s'accorde naturellement avec « 공원에서 » (dans le parc).", 'de': "„운동합니다“ bedeutet „Sport treiben“. Jeden Morgen im Park Sport zu treiben, ist eine ganz natürliche Aktivität. „요리합니다“ = kochen, „청소합니다“ = putzen, „세수합니다“ = sich das Gesicht waschen. Nur „운동합니다“ passt ganz natürlich zu „공원에서“ (im Park)."})),
      MockQuestion(id: "ko_topik1_mock_q002", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "빈칸에 알맞은 것을 고르십시오.\n\n오늘은 날씨가 __________. 산책하기 좋아요.", questionEn: "Choose the correct word: 'Today the weather is ___. It's good for a walk.'", correctAnswer: "좋습니다", distractors: const ["나쁩니다", "덥습니다", "춥습니다"], explanation: const LocalizedText({'en': "좋습니다 means 'good'. 날씨가 좋습니다 = the weather is good — matching with 산책하기 좋아요 (good for a walk). 나쁩니다 = bad, 덥습니다 = hot, 춥습니다 = cold — none of these would make it good for a walk.", 'ko': "'좋습니다'는 'good'이라는 뜻입니다. 날씨가 좋아서 산책하기 좋다는 문맥이 자연스럽습니다.", 'ja': "「좋습니다」は「良い」という意味です。「날씨가 좋습니다」＝「天気が良い」――これは「산책하기 좋아요」（散歩に最適）と一致します。「나쁩니다」＝「悪い」、「덥습니다」＝「暑い」、「춥습니다」＝「寒い」――これらはいずれも散歩に適しているとは言えません。", 'zh': "“좋습니다”意为“好”。“날씨가 좋습니다”=“天气很好”——与“산책하기 좋아요”（适合散步）相呼应。“나쁩니다”=“不好”，“덥습니다”=“热”，“춥습니다”=“冷”——这些情况都不适合散步。", 'zh_TW': "「좋습니다」的意思是「好」。天氣很好 = 天氣很好 — 對應於「適合散步」（good for a walk）。「不好」= 不好、「熱」= 熱、「冷」= 冷 — 這些情況都不適合散步。", 'es': "«좋습니다» significa «bueno». «날씨가 좋습니다» = hace buen tiempo — lo que encaja con «산책하기 좋아요» (es un buen día para dar un paseo). «나쁩니다» = malo, «덥습니다» = hace calor, «춥습니다» = hace frío — ninguna de estas situaciones sería buena para dar un paseo.", 'fr': "« 좋습니다 » signifie « bien ». « 날씨가 좋습니다 » = « il fait beau » — ce qui correspond à « 산책하기 좋아요 » (idéal pour se promener). « 나쁩니다 » = mauvais, « 덥습니다 » = chaud, « 춥습니다 » = froid — aucune de ces conditions ne rendrait la promenade agréable.", 'de': "„좋습니다“ bedeutet „gut“. „날씨가 좋습니다“ = das Wetter ist gut – passend zu „산책하기 좋아요“ (gut für einen Spaziergang). „나쁩니다“ = schlecht, „덥습니다“ = heiß, „춥습니다“ = kalt – bei keinem dieser Fälle wäre es gut für einen Spaziergang."})),
      MockQuestion(id: "ko_topik1_mock_q003", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "빈칸에 알맞은 것을 고르십시오.\n\n저는 어제 친구를 __________.", questionEn: "Choose the correct word: 'I ___ a friend yesterday.'", correctAnswer: "만났습니다", distractors: const ["만들었습니다", "먹었습니다", "보냈습니다"], explanation: const LocalizedText({'en': "만났습니다 means 'met'. 친구를 만나다 = to meet a friend. 만들었습니다 = made, 먹었습니다 = ate, 보냈습니다 = sent. Only 만났습니다 is appropriate with 친구를 (friend as object).", 'ko': "'만났습니다'는 'met'이라는 뜻입니다. '친구를 만나다'는 자연스러운 표현입니다.", 'ja': "「만났습니다」は「会いました」という意味です。「친구를 만나다」＝「友人に会う」。「만들었습니다」＝「作りました」、「먹었습니다」＝「食べました」、「보냈습니다」＝「送りました」。「만났습니다」は「친구」を目的語とする場合のみ適切です。", 'zh': "“만났습니다”意为“见过”。“친구를 만나다”=“见到朋友”。“만들었습니다”=“做过”，“먹었습니다”=“吃过”，“보냈습니다”=“寄过”。只有“만났습니다”与“친구”（朋友作为宾语）搭配使用才合适。", 'zh_TW': "「만났습니다」的意思是「見到」。「친구를 만나다」＝見到朋友。「만들었습니다」＝製作了，「먹었습니다」＝吃了，「보냈습니다」＝寄出了。只有「만났습니다」搭配「친구」作為賓語時才合適。", 'es': "«만났습니다» significa «se encontró». «친구를 만나다» = encontrarse con un amigo. «만들었습니다» = hizo, «먹었습니다» = comió, «보냈습니다» = envió. Solo «만났습니다» es adecuado con «친구» (amigo como objeto).", 'fr': "« 만났습니다 » signifie « a rencontré ». « 친구를 만나다 » = « rencontrer un ami ». « 만들었습니다 » = « a fabriqué », « 먹었습니다 » = « a mangé », « 보냈습니다 » = « a envoyé ». Seule la forme « 만났습니다 » est correcte avec « 친구를 » (ami en complément d'objet).", 'de': "„만났습니다“ bedeutet „getroffen“. „친구를 만나다“ = einen Freund treffen. „만들었습니다“ = gemacht, „먹었습니다“ = gegessen, „보냈습니다“ = geschickt. Nur „만났습니다“ passt zu „친구“ (Freund als Objekt)."})),
      MockQuestion(id: "ko_topik1_mock_q004", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "빈칸에 알맞은 것을 고르십시오.\n\n가방이 너무 __________. 좀 도와주세요.", questionEn: "Choose the correct word: 'The bag is too ___. Please help me.'", correctAnswer: "무겁습니다", distractors: const ["가볍습니다", "작습니다", "쌉니다"], explanation: const LocalizedText({'en': "무겁습니다 means 'heavy'. When a bag is too heavy, asking for help makes sense. 가볍습니다 = light (wouldn't require help), 작습니다 = small, 쌉니다 = cheap. Only 무겁습니다 fits the request for help.", 'ko': "'무겁습니다'는 'heavy'라는 뜻입니다. 가방이 무거워서 도움을 요청하는 상황이 자연스럽습니다.", 'ja': "「무겁습니다」は「重い」という意味です。バッグが重すぎる場合は、助けを求めるのが理にかなっています。「가볍습니다」＝軽い（助けは必要ない）、「작습니다」＝小さい、「쌉니다」＝安い。助けを求める文脈に当てはまるのは「무겁습니다」だけです。", 'zh': "“무겁습니다”的意思是“重”。当包太重时，寻求帮助是合理的。“가볍습니다”=轻（不需要帮助），“작습니다”=小，“쌉니다”=便宜。只有“무겁습니다”符合寻求帮助的情况。", 'zh_TW': "「무겁습니다」的意思是「重」。當包包太重時，請求協助是合理的。「가볍습니다」＝輕（不需要幫忙）、「작습니다」＝小、「쌉니다」＝便宜。只有「무겁습니다」符合請求協助的情況。", 'es': "«무겁습니다» significa «pesado». Cuando una bolsa pesa demasiado, tiene sentido pedir ayuda. «가볍습니다» = ligero (no requeriría ayuda), «작습니다» = pequeño, «쌉니다» = barato. Solo «무겁습니다» encaja con la petición de ayuda.", 'fr': "« 무겁습니다 » signifie « lourd ». Lorsqu'un sac est trop lourd, il est logique de demander de l'aide. « 가볍습니다 » = léger (ne nécessiterait pas d'aide), « 작습니다 » = petit, « 쌉니다 » = bon marché. Seul « 무겁습니다 » correspond à la demande d'aide.", 'de': "„무겁습니다“ bedeutet „schwer“. Wenn eine Tasche zu schwer ist, ist es sinnvoll, um Hilfe zu bitten. „가볍습니다“ = leicht (dafür wäre keine Hilfe nötig), „작습니다“ = klein, „쌉니다“ = billig. Nur „무겁습니다“ passt zu der Bitte um Hilfe."})),
      MockQuestion(id: "ko_topik1_mock_q005", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "빈칸에 알맞은 것을 고르십시오.\n\n저는 매일 학교에 __________.", questionEn: "Choose the correct word: 'I ___ to school every day.'", correctAnswer: "갑니다", distractors: const ["잡니다", "삽니다", "받습니다"], explanation: const LocalizedText({'en': "갑니다 means 'go'. 학교에 가다 = to go to school. 잡니다 = sleep, 삽니다 = buy, 받습니다 = receive. Only 갑니다 works with 학교에 (to school).", 'ko': "'갑니다'는 'go'라는 뜻입니다. '학교에 가다'는 기본적인 표현입니다.", 'ja': "「갑니다」は「行く」という意味です。「학교에 가다」＝「学校に行く」。「잡니다」＝「寝る」、「삽니다」＝「買う」、「받습니다」＝「受け取る」。「갑니다」は「학교에（学校に）」と組み合わせて使う場合のみです。", 'zh': "“갑니다”意为“去”。“학교에 가다”=去上学。“잡니다”=睡觉，“삽니다”=买，“받습니다”=收到。只有“갑니다”能与“학교에”（去学校）搭配使用。", 'zh_TW': "「갑니다」的意思是「去」。「학교에 가다」＝去上學。「잡니다」＝睡覺，「삽니다」＝買，「받습니다」＝收到。只有「갑니다」能與「학교에」（去上學）搭配使用。", 'es': "«갑니다» significa «ir». «학교에 가다» = ir al colegio. «잡니다» = dormir, «삽니다» = comprar, «받습니다» = recibir. Solo «갑니다» se usa con «학교에» (al colegio).", 'fr': "« 갑니다 » signifie « aller ». « 학교에 가다 » = aller à l'école. « 잡니다 » = dormir, « 삽니다 » = acheter, « 받습니다 » = recevoir. Seul « 갑니다 » s'utilise avec « 학교에 » (à l'école).", 'de': "„갑니다“ bedeutet „gehen“. „학교에 가다“ = zur Schule gehen. „잡니다“ = schlafen, „삽니다“ = kaufen, „받습니다“ = erhalten. Nur „갑니다“ passt zu „학교에“ (zur Schule)."})),
      MockQuestion(id: "ko_topik1_mock_q006", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "빈칸에 알맞은 것을 고르십시오.\n\n이 음식은 너무 __________. 물을 주세요.", questionEn: "Choose the correct word: 'This food is too ___. Please give me water.'", correctAnswer: "맵습니다", distractors: const ["달콤합니다", "시원합니다", "따뜻합니다"], explanation: const LocalizedText({'en': "맵습니다 means 'spicy'. Asking for water because food is spicy is a natural reaction. 달콤합니다 = sweet, 시원합니다 = cool/refreshing, 따뜻합니다 = warm. Only spicy food makes someone ask for water urgently.", 'ko': "'맵습니다'는 'spicy'라는 뜻입니다. 매운 음식을 먹고 물을 찾는 상황은 자연스럽습니다.", 'ja': "「맵습니다」は「辛い」という意味です。料理が辛いから水を頼むのは、ごく自然な反応です。「달콤합니다」＝甘い、「시원합니다」＝涼しい／爽やか、「따뜻합니다」＝温かい。辛い料理だけが、人を焦って水を頼ませるのです。", 'zh': "“맵습니다”的意思是“辣”。因为食物太辣而要水喝，是一种自然反应。“달콤합니다”=甜，“시원합니다”=凉爽/清爽，“따뜻합니다”=温暖。只有吃辣的食物才会让人急着要水喝。", 'zh_TW': "「맵습니다」的意思是「辣」。因為食物太辣而要水喝，是人之常情。달콤합니다 = 甜，시원합니다 = 涼爽／清爽，따뜻합니다 = 溫熱。只有吃辣的食物才會讓人急著要水喝。", 'es': "«맵습니다» significa «picante». Pedir agua porque la comida pica es una reacción natural. «달콤합니다» = dulce, «시원합니다» = fresco/refrescante, «따뜻합니다» = caliente. Solo la comida picante hace que alguien pida agua con urgencia.", 'fr': "« 맵습니다 » signifie « épicé ». Demander de l'eau parce que la nourriture est épicée est une réaction naturelle. « 달콤합니다 » = sucré, « 시원합니다 » = frais/rafraîchissant, « 따뜻합니다 » = chaud. Seule la nourriture épicée pousse quelqu'un à demander de l'eau de toute urgence.", 'de': "„맵습니다“ bedeutet „scharf“. Nach Wasser zu fragen, weil das Essen scharf ist, ist eine ganz natürliche Reaktion. „달콤합니다“ = süß, „시원합니다“ = kühl/erfrischend, „따뜻합니다“ = warm. Nur bei scharfem Essen fragt man dringend nach Wasser."})),
      MockQuestion(id: "ko_topik1_mock_q007", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "빈칸에 알맞은 것을 고르십시오.\n\n저는 음악을 __________ 좋아합니다.", questionEn: "Choose the correct word: 'I like ___ music.'", correctAnswer: "듣는 것을", distractors: const ["보는 것을", "먹는 것을", "입는 것을"], explanation: const LocalizedText({'en': "듣다 means 'to listen'. 음악을 듣다 = to listen to music — the standard collocation. 보다 = watch, 먹다 = eat, 입다 = wear. Only 듣다 pairs with 음악 (music).", 'ko': "'듣다'는 'listen'이라는 뜻입니다. '음악을 듣다'는 자연스러운 표현입니다.", 'ja': "「듣다」は「聞く」という意味です。「음악을 듣다」＝「音楽を聴く」— これが標準的な組み合わせです。「보다」＝「見る」、「먹다」＝「食べる」、「입다」＝「着る」。音楽（음악）と組み合わされるのは「듣다」だけです。", 'zh': "“듣다”意为“听”。“음악을 듣다”即“听音乐”——这是标准搭配。“보다”意为“看”，“먹다”意为“吃”，“입다”意为“穿”。只有“듣다”与“음악”（音乐）搭配使用。", 'zh_TW': "「듣다」的意思是「聽」。「음악을 듣다」＝「聽音樂」——這是標準的搭配。「보다」＝「看」，「먹다」＝「吃」，「입다」＝「穿」。只有「듣다」會與「음악」（音樂）搭配。", 'es': "«듣다» significa «escuchar». «음악을 듣다» = «escuchar música»: la combinación habitual. «보다» = «ver», «먹다» = «comer», «입다» = «vestir». Solo «듣다» se combina con «음악» (música).", 'fr': "« 듣다 » signifie « écouter ». « 음악을 듣다 » = « écouter de la musique » — c'est la tournure standard. « 보다 » = regarder, « 먹다 » = manger, « 입다 » = porter. Seul « 듣다 » s'associe à « 음악 » (musique).", 'de': "„듣다“ bedeutet „hören“. „음악을 듣다“ = „Musik hören“ – die übliche Wortkombination. „보다“ = „sehen“, „먹다“ = „essen“, „입다“ = „tragen“. Nur „듣다“ wird mit „음악“ (Musik) kombiniert."})),
      MockQuestion(id: "ko_topik1_mock_q008", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "빈칸에 알맞은 것을 고르십시오.\n\n저는 한국어를 __________.", questionEn: "Choose the correct word: 'I ___ Korean.'", correctAnswer: "공부합니다", distractors: const ["여행합니다", "운동합니다", "전화합니다"], explanation: const LocalizedText({'en': "공부합니다 means 'study'. 한국어를 공부하다 = to study Korean — the most natural collocation. 여행합니다 = travel, 운동합니다 = exercise, 전화합니다 = call on the phone. Only 공부합니다 pairs naturally with 한국어 (Korean language).", 'ko': "'공부합니다'는 'study'라는 뜻입니다. '한국어를 공부하다'는 자연스러운 표현입니다.", 'ja': "「공부합니다」は「勉強する」という意味です。「한국어를 공부하다」＝「韓国語を勉強する」——これが最も自然な組み合わせです。「여행합니다」＝「旅行する」、「운동합니다」＝「運動する」、「전화합니다」＝「電話をかける」。韓国語（Korean language）と自然に組み合わさるのは、「공부합니다」だけです。", 'zh': "“공부합니다”意为“学习”。“한국어를 공부하다”=学习韩语——这是最自然的搭配。“여행합니다”=旅行，“운동합니다”=锻炼，“전화합니다”=打电话。只有“공부합니다”与“한국어”（韩语）搭配起来才自然。", 'zh_TW': "「공부합니다」的意思是「學習」。「한국어를 공부하다」＝「學習韓語」——這是最自然的搭配。 「여행합니다」＝「旅行」，「운동합니다」＝「運動」，「전화합니다」＝「打電話」。只有「공부합니다」能自然地與「한국어」（韓語）搭配。", 'es': "«공부합니다» significa «estudiar». «한국어를 공부하다» = estudiar coreano: la combinación más natural. «여행합니다» = viajar, «운동합니다» = hacer ejercicio, «전화합니다» = llamar por teléfono. Solo «공부합니다» se combina de forma natural con «한국어» (idioma coreano).", 'fr': "« 공부합니다 » signifie « étudier ». « 한국어를 공부하다 » = étudier le coréen — c'est la combinaison la plus naturelle. « 여행합니다 » = voyager, « 운동합니다 » = faire de l'exercice, « 전화합니다 » = téléphoner. Seul « 공부합니다 » s'associe naturellement avec « 한국어 » (la langue coréenne).", 'de': "„공부합니다“ bedeutet „lernen“. „한국어를 공부하다“ = Koreanisch lernen – die natürlichste Wortkombination. „여행합니다“ = reisen, „운동합니다“ = Sport treiben, „전화합니다“ = telefonieren. Nur „공부합니다“ passt ganz natürlich zu „한국어“ (koreanische Sprache)."})),
      MockQuestion(id: "ko_topik1_mock_q009", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "빈칸에 알맞은 것을 고르십시오.\n\n우리 집에는 고양이가 __________.", questionEn: "Choose the correct word: 'There ___ a cat in our house.'", correctAnswer: "있습니다", distractors: const ["없습니다", "합니다", "됩니다"], explanation: const LocalizedText({'en': "있습니다 means 'there is/are'. Noun + 이/가 있습니다 = there is a noun. While 없습니다 (there isn't) is grammatically possible, 있습니다 is the neutral choice and tests the basic existence pattern. 합니다 = do, 됩니다 = become.", 'ko': "'있습니다'는 존재를 나타내는 동사입니다. '고양이가 있습니다'는 가장 기본적인 존재 표현입니다.", 'ja': "「있습니다」は「～がある」という意味です。名詞 + 이/가 있습니다 = 「～がある」。「없습니다」（～がない）も文法的には可能ですが、「있습니다」が中立的な表現であり、基本的な存在のパターンを確認するためのものです。「합니다」＝「～する」、「됩니다」＝「～になる」。", 'zh': "“있습니다”意为“有”。名词 + 이/가 있습니다 = 有一个名词。虽然 “없습니다”（没有）在语法上是成立的，但 “있습니다”是中性表达，用于测试基本的“存在”句式。“합니다” = 做，“됩니다” = 变成。", 'zh_TW': "「있습니다」意為「有」。名詞 + 이/가 있습니다 = 有一（個）名詞。雖然「없습니다」（沒有）在語法上也是成立的，但「있습니다」是中性選擇，用來測試基本的「存在」句型。「합니다」意為「做」，「됩니다」意為「變成」。", 'es': "«있습니다» significa «hay». Sustantivo + 이/가 있습니다 = hay un sustantivo. Aunque «없습니다» (no hay) es gramaticalmente posible, «있습니다» es la opción más neutra y pone a prueba el patrón básico de existencia. «합니다» = hacer, «됩니다» = convertirse.", 'fr': "« 있습니다 » signifie « il y a ». Nom + 이/가 있습니다 = il y a un nom. Bien que « 없습니다 » (il n'y a pas) soit grammaticalement possible, « 있습니다 » est le choix neutre et permet de tester la structure de base de l'existence. « 합니다 » = faire, « 됩니다 » = devenir.", 'de': "„있습니다“ bedeutet „es gibt“. Substantiv + 이/가 있습니다 = es gibt ein Substantiv. Während „없습니다“ (es gibt nicht) grammatikalisch möglich ist, ist „있습니다“ die neutrale Variante und dient zur Überprüfung des grundlegenden Existenzmusters. „합니다“ = tun, „됩니다“ = werden."})),
      MockQuestion(id: "ko_topik1_mock_q010", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "빈칸에 알맞은 것을 고르십시오.\n\n주말에 친구들과 __________ 영화를 봤습니다.", questionEn: "Choose the correct word: 'On the weekend, I watched a movie ___ my friends.'", correctAnswer: "함께", distractors: const ["혼자", "아까", "항상"], explanation: const LocalizedText({'en': "함께 means 'together'. 친구들과 함께 = together with friends — matches the plural 친구들. 혼자 = alone (contradicts 친구들과), 아까 = a while ago, 항상 = always. Only 함께 works with 친구들과.", 'ko': "'함께'는 'together'라는 뜻입니다. '친구들과 함께'는 자연스러운 표현입니다.", 'ja': "「함께」は「一緒に」という意味です。「친구들과 함께」＝「友達と一緒に」— 複数形の「친구들」と一致します。「혼자」＝「一人で」（「친구들과」と矛盾します）、「아까」＝「さっき」、「항상」＝「いつも」。「함께」は「친구들과」と組み合わせてのみ使われます。", 'zh': "“함께”意为“一起”。“친구들과 함께”=“和朋友们一起”——与复数形式的“친구들”相匹配。“혼자”=“独自”（与“친구들과”矛盾），“아까”=“刚才”，“항상”=“总是”。只有“함께”能与“친구들과”搭配使用。", 'zh_TW': "「함께」意為「一起」。朋友들과 함께 = 和朋友們一起 — 與複數形式的「친구들」相符。혼자 = 獨自（與「친구들과」相矛盾），아까 = 剛才，항상 = 總是。只有「함께」能與「친구들과」搭配使用。", 'es': "«함께» significa «juntos». «친구들과 함께» = «juntos con amigos» — concuerda con el plural «친구들». «혼자» = «solo» (contrasta con «친구들과»), «아까» = «hace un rato», «항상» = «siempre». Solo «함께» concuerda con «친구들과».", 'fr': "« 함께 » signifie « ensemble ». « 친구들과 함께 » = « avec des amis » — correspond au pluriel « 친구들 ». « 혼자 » = « seul » (contradit « 친구들과 »), « 아까 » = « tout à l'heure », « 항상 » = « toujours ». Seul « 함께 » s'utilise avec « 친구들과 ».", 'de': "„함께“ bedeutet „zusammen“. „친구들과 함께“ = „zusammen mit Freunden“ – passt zum Plural „친구들“. „혼자“ = „allein“ (widerspricht „친구들과“), „아까“ = „vorhin“, „항상“ = „immer“. Nur „함께“ passt zu „친구들과“."})),
      MockQuestion(id: "ko_topik1_mock_q011", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "빈칸에 알맞은 말을 쓰십시오.\n\n내일 학교에 __________. (가다 — future intention)", questionEn: "Fill in the blank: 'I will ___ to school tomorrow.' (가다 — future intention using 겠)", correctAnswer: "갈 거예요", distractors: const ["가요", "갔어요", "가고 싶어요"], explanation: const LocalizedText({'en': "겠 is used to express future intention or will. 가다 → 가 + 겠 + 습니다 = 가겠습니다 (I will go). 갔습니다 = went (past), 갑니다 = go (present), 가고 있습니다 = is going (progressive). For 내일 (tomorrow), future form is required.", 'ko': "'겠'은 미래나 의지를 나타냅니다. '가다'에 '겠'을 붙여 '가겠습니다'가 됩니다. '내일'은 미래이므로 미래형이 필요합니다.", 'ja': "「겠」は、将来の意図や意志を表す際に使われます。가다 → 가 + 겠 + 습니다 = 가겠습니다（行きます）。갔습니다 = 行きました（過去）、갑니다 = 行きます（現在）、가고 있습니다 = 行っています（進行形）。「내일」（明日）については、未来形が必要です。", 'zh': "“겠”用于表达未来的意图或意愿。가다 → 가 + 겠 + 습니다 = 가겠습니다（我要去）。갔습니다 = 去了（过去），갑니다 = 去（现在），가고 있습니다 = 正在去（进行时）。对于“내일”（明天），需要使用将来时。", 'zh_TW': "「겠」用於表達未來的意圖或意志。例如：가다 → 가 + 겠 + 습니다 = 가겠습니다（我會去）。갔습니다 = 去了（過去式），갑니다 = 去（現在式），가고 있습니다 = 正在去（進行式）。對於「내일」（明天），必須使用未來式。", 'es': "«-겠» se utiliza para expresar una intención o voluntad futura. «가다» → «가» + «-겠» + «-습니다» = «가겠습니다» (iré). «갔습니다» = fui (pasado), «갑니다» = voy (presente), «가고 있습니다» = estoy yendo (progresivo). Para «내일» (mañana), se requiere la forma futura.", 'fr': "« 겠 » est utilisé pour exprimer une intention ou une volonté future. 가다 → 가 + 겠 + 습니다 = 가겠습니다 (j'irai). 갔습니다 = suis allé (passé), 갑니다 = vais (présent), 가고 있습니다 = suis en train d'aller (progressif). Pour 내일 (demain), la forme future est requise.", 'de': "„-겠“ wird verwendet, um eine zukünftige Absicht oder einen Willen auszudrücken. 가다 → 가 + 겠 + 습니다 = 가겠습니다 (Ich werde gehen). 갔습니다 = ging (Vergangenheit), 갑니다 = gehe (Gegenwart), 가고 있습니다 = gehe gerade (Fortlaufende Zeit). Für 내일 (morgen) ist die Zukunftsform erforderlich."})),
      MockQuestion(id: "ko_topik1_mock_q012", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "빈칸에 알맞은 말을 쓰십시오.\n\n한국에 __________ 적이 있습니까? (가다 — past experience)", questionEn: "Fill in the blank: 'Have you ever ___ to Korea?' (가다 — past experience with ㄴ 적이 있다)", correctAnswer: "가 본", distractors: const ["가는", "가서", "가면"], explanation: const LocalizedText({'en': "The grammar pattern V + (으)ㄴ 적이 있다 expresses past experience ('have ever done'). 가다 → 가 + ㄴ → 간, but with 보다 (try): 가 보다 → 가 본 적이 있다 = have been (to). This is the standard way to ask about travel experience. 간 적이 있다 (without 보다) is also possible but 가 본 적이 있다 is more natural.", 'ko': "'ㄴ 적이 있다'는 과거의 경험을 나타냅니다. '가 보다'의 활용형 '가 본 적이 있다'가 '가본 적이 있다'로, 여행 경험을 물을 때 가장 자연스러운 표현입니다.", 'ja': "文型「V + (으)ㄴ 적이 있다」は、過去の経験（「～したことがある」）を表します。「가다」の場合、「가 + ㄴ」で「간」となりますが、「보다（～してみる）」の場合は、「가 보다」となり、「가 본 적이 있다」＝「～したことがある」となります。これは旅行の経験について尋ねる際の標準的な表現です。「간 적이 있다」（「보다」なし）も可能です。「가 본 적이 있다」の方がより自然です。", 'zh': "语法结构 V + (으)ㄴ 적이 있다 表示过去经历（“曾经做过”）。以“가다”（去）为例：가 + ㄴ → 간，但若使用“보다”（尝试）：가 보다 → 가 본 적이 있다 = have been (to)。这是询问旅行经历的标准表达方式。虽然也可以说 “간 적이 있다”（不带“보다”），但 “가 본 적이 있다” 更自然。", 'zh_TW': "語法結構 V + (으)ㄴ 적이 있다 表示過去的經驗（「曾經做過」）。以「가다」（去）為例：가 + ㄴ → 간，但若搭配「보다」（試過）：가 보다 → 가 본 적이 있다 = have been (to)。這是詢問旅行經驗的標準說法。雖然也可以說「간 적이 있다」（不帶「보다」），但「가 본 적이 있다」聽起來更自然。", 'es': "La estructura gramatical V + (으)ㄴ 적이 있다 expresa una experiencia pasada («haber hecho alguna vez»). 가다 → 가 + ㄴ → 간, pero con 보다 (probar): 가 보다 → 가 본 적이 있다 = haber estado (en). Esta es la forma habitual de preguntar por experiencias de viaje. También es posible decir 간 적이 있다 (sin 보다), pero 가 본 적이 있다 resulta más natural.", 'fr': "La structure grammaticale V + (으)ㄴ 적이 있다 exprime une expérience passée (« avoir déjà fait »). 가다 → 가 + ㄴ → 간, mais avec 보다 (essayer) : 가 보다 → 가 본 적이 있다 = avoir été (à). C'est la façon standard de s'enquérir d'une expérience de voyage. 간 적이 있다 (sans 보다) est également possible, mais 가 본 적이 있다 est plus naturel.", 'de': "Das Grammatikmuster V + (으)ㄴ 적이 있다 drückt eine Erfahrung in der Vergangenheit aus („jemals getan haben“). 가다 → 가 + ㄴ → 간, aber bei 보다 (sehen): 가 보다 → 가 본 적이 있다 = (dort) gewesen sein. Dies ist die übliche Art, nach Reiseerfahrungen zu fragen. 간 적이 있다 (ohne 보다) ist ebenfalls möglich, aber 가 본 적이 있다 klingt natürlicher."})),
      MockQuestion(id: "ko_topik1_mock_q013", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "빈칸에 알맞은 말을 쓰십시오.\n\n비빔밥을 __________ 합니다. (먹다 — desire)", questionEn: "Fill in the blank: 'I want to ___ bibimbap.' (먹다 — desire using 고 싶다)", correctAnswer: "먹고 싶", distractors: const ["먹어요", "먹었어요", "먹을 거예요"], explanation: const LocalizedText({'en': "고 싶다 expresses desire ('want to do'). 먹다 → 먹 + 고 싶습니다 = 먹고 싶습니다 (want to eat). 먹습니다 = eat (statement), 먹었습니다 = ate (past), 먹겠습니다 = will eat (future intention). Only 고 싶다 expresses the desire correctly.", 'ko': "'고 싶다'는 희망이나 바람을 나타냅니다. '먹다'에 '고 싶다'를 붙여 '먹고 싶습니다'가 됩니다.", 'ja': "「고 싶다」は願望（「～したい」）を表します。「먹다」→「먹」＋「고 싶습니다」＝「먹고 싶습니다」（食べたい）。「먹습니다」＝「食べる」（現在形）、「먹었습니다」＝「食べました」（過去形）、「먹겠습니다」＝「食べます」（未来・意志）。「고 싶다」だけが正しく願望を表します。", 'zh': "“고 싶다”表达的是愿望（“想做”）。吃 → 먹 + 고 싶습니다 = 먹고 싶습니다（想吃）。먹습니다 = 吃（陈述句），먹었습니다 = 吃了（过去式），먹겠습니다 = 会吃（未来意向）。只有“고 싶다”能正确表达这种愿望。", 'zh_TW': "「고 싶다」表達的是「想要做」的意願。吃 → 먹 + 고 싶습니다 = 먹고 싶습니다（想吃）。먹습니다 = 吃（陳述句），먹었습니다 = 吃了（過去式），먹겠습니다 = 將吃（未來意向）。只有「고 싶다」能正確表達這種意願。", 'es': "«고 싶다» expresa un deseo («querer hacer»). «먹다» → «먹» + «고 싶습니다» = «먹고 싶습니다» (quiero comer). «먹습니다» = comer (presente), «먹었습니다» = comí (pasado), «먹겠습니다» = comeré (intención futura). Solo «고 싶다» expresa correctamente el deseo.", 'fr': "« 고 싶다 » exprime un désir (« vouloir faire »). Manger → 먹 + 고 싶습니다 = 먹고 싶습니다 (vouloir manger). 먹습니다 = manger (présent), 먹었습니다 = a mangé (passé), 먹겠습니다 = mangera (intention future). Seul « 고 싶다 » exprime correctement le désir.", 'de': "„고 싶다“ drückt einen Wunsch aus („tun wollen“). „먹다“ → „먹“ + „고 싶습니다“ = „먹고 싶습니다“ (essen wollen). „먹습니다“ = essen (Aussage), „먹었습니다“ = aß (Vergangenheit), „먹겠습니다“ = werde essen (zukünftige Absicht). Nur „고 싶다“ drückt den Wunsch korrekt aus."})),
      MockQuestion(id: "ko_topik1_mock_q014", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "빈칸에 알맞은 말을 쓰십시오.\n\n내일은 __________ 더 춥겠습니다. (오늘 — comparison)", questionEn: "Fill in the blank: 'Tomorrow will be colder ___ today.' (오늘 — comparison using 보다)", correctAnswer: "오늘보다", distractors: const ["어제보다", "내일", "오늘은"], explanation: const LocalizedText({'en': "보다 is the comparison particle meaning 'than'. 오늘 + 보다 = 오늘보다 = than today. 오늘은 = as for today (topic), 오늘이 = today (subject), 오늘도 = today also. Only 보다 creates the comparison 'colder than today'.", 'ko': "'보다'는 비교를 나타내는 조사입니다. '오늘보다'는 'than today'라는 뜻으로, 더 춥다는 비교 표현과 자연스럽게 연결됩니다.", 'ja': "「보다」は「～より」という意味の比較助詞です。「오늘」＋「보다」＝「오늘보다」＝「今日より」。「오늘은」＝「今日については」（話題）、「오늘이」＝「今日」（主語）、「오늘도」＝「今日も」。比較表現「오늘보다」は、「보다」だけで「今日より寒い」という意味になります。", 'zh': "“보다”是表示“比……更……”的比较助词。오늘 + 보다 = 오늘보다 = 比今天。오늘은 = 至于今天（话题），오늘이 = 今天（主语），오늘도 = 今天也。只有“보다”能构成“比今天更冷”这样的比较句。", 'zh_TW': "「보다」是表示「比」的比較助詞。今天 + 보다 = 오늘보다 = 比今天。오늘은 = 至於今天（話題），오늘이 = 今天（主語），오늘도 = 今天也。只有「보다」能構成「比今天更冷」這樣的比較句。", 'es': "«보다» es la partícula de comparación que significa «que». Hoy + 보다 = hoy que = que hoy. Hoy es = en cuanto a hoy (tema), hoy es = hoy (sujeto), hoy también = hoy también. Solo «보다» crea la comparación «más frío que hoy».", 'fr': "« 보다 » est la particule de comparaison qui signifie « que ». « 오늘 » + « 보다 » = « 오늘보다 » = « que aujourd'hui ». « 오늘은 » = « quant à aujourd'hui » (sujet), « 오늘이 » = « aujourd'hui » (sujet), « 오늘도 » = « aujourd'hui aussi ». Seul « 보다 » permet de former la comparaison « plus froid qu'aujourd'hui ».", 'de': "„보다“ ist die Vergleichspartikel, die „als“ bedeutet. „오늘“ + „보다“ = „오늘보다“ = „als heute“. „오늘은“ = „was heute betrifft“ (Thema), „오늘이“ = „heute“ (Subjekt), „오늘도“ = „auch heute“. Nur „보다“ bildet den Vergleich „kälter als heute“."})),
      MockQuestion(id: "ko_topik1_mock_q015", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "빈칸에 알맞은 말을 쓰십시오.\n\n시간이 __________ 빨리 갔어요. (없다 — reason using 아/어서)", questionEn: "Fill in the blank: 'Time passed quickly ___ there was none.' (없다 — reason using 아/어서)", correctAnswer: "없어서", distractors: const ["없고", "없으면", "없지만"], explanation: const LocalizedText({'en': "아/어서 expresses reason or cause. 없다 → 없 + 어서 = 없어서 = because there is none. 없고 = none, and (~고 is listing), 없지만 = none, but (~지만 is contrast), 없으니까 = because none (~니까 is also reason but more subjective/colloquial). In formal written tests, 어서 is preferred for neutral cause-effect.", 'ko': "'아/어서'는 이유나 원인을 나타냅니다. '없다'에 '어서'를 붙여 '없어서'가 됩니다. 객관적인 인과관계를 나타낼 때 사용합니다.", 'ja': "「아/어서」は理由や原因を表します。「없다」→「없」＋「어서」＝「없어서」＝「ないから」。「없고」＝「ない」（「~고」は列挙を表す）、「하지만」＝「ないが」（「~지만」は対比を表す）、「없으니까」＝「ないから」（「~니까」も理由を表すが、より主観的・口語的）。正式な筆記試験では、中立的な因果関係を表現する場合、「어서」の使用が推奨されます。", 'zh': "“아/어서”用于表达理由或原因。“없다”→“없”+“어서”=“없어서”=“因为没有”。“없고”表示“没有”（“~고”表示列举），“없지만”表示“虽然没有”（“~지만”表示对比），“없으니까”表示“因为没有”（“~니까”也表示理由，但更主观、口语化）。在正式的书面考试中，建议使用“어서”来表达中性的因果关系。", 'zh_TW': "「아/어서」用來表達理由或原因。「없다」→「없」＋「어서」＝「없어서」＝「因為沒有」。其中，「없고」表示「沒有」（「~고」用於列舉）、「없지만」表示「雖然沒有」（「~지만」用於對比），而「없으니까」則表示「因為沒有」（「~니까」雖也表示理由，但語感更為主觀且口語化）。在正式的書面考試中，若要表達中性的因果關係，通常建議使用「어서」。", 'es': "«아/어서» expresa una razón o causa. «없다» → «없» + «어서» = «없어서» = «porque no hay». «없고» = «ninguno» (y «~고» indica enumeración), «없지만» = «ninguno, pero» (y «~지만» indica contraste), «없으니까» = «porque no hay» (y «~니까» también indica razón, pero es más subjetivo/coloquial). En exámenes escritos formales, se prefiere «어서» para expresar una relación causa-efecto neutra.", 'fr': "« 아/어서 » exprime une raison ou une cause. « 없다 » → « 없 » + « 어서 » = « 없어서 » = « parce qu’il n’y en a pas ». « 없고 » = « aucun » (avec « ~고 » pour énumérer), « 없지만 » = « aucun, mais » (avec « ~지만 » pour marquer un contraste), « 없으니까 » = « parce qu’il n’y en a pas » (avec « ~니까 » qui exprime également une raison, mais de manière plus subjective et familière). Dans les examens écrits formels, on préfère utiliser « 어서 » pour exprimer un rapport de cause à effet de manière neutre.", 'de': "„아/어서“ drückt einen Grund oder eine Ursache aus. „없다“ → „없“ + „어서“ = „없어서“ = „weil es keine gibt“. „없고“ = „keine“, und „~고“ drückt eine Aufzählung aus; „없지만“ = „keine, aber“ – „~지만“ drückt einen Kontrast aus; „없으니까“ = „weil keine“ – „~니까“ drückt ebenfalls einen Grund aus, ist jedoch subjektiver und umgangssprachlicher. In formellen schriftlichen Prüfungen wird „어서“ bevorzugt, um eine neutrale Ursache-Wirkungs-Beziehung auszudrücken."})),
      MockQuestion(id: "ko_topik1_mock_q016", section: "reading", type: MockQuestionType.multiple_choice, question: "도서관에 어떻게 갑니까?", questionEn: "How does the person go to the library?", correctAnswer: "걸어서 갑니다", distractors: const ["버스로 갑니다", "지하철로 갑니다", "자전거로 갑니다"], explanation: const LocalizedText({'en': "The passage says 걸어서 10분쯤 걸립니다 (it takes about 10 minutes on foot), indicating the person walks. Bus, subway, and bicycle are not mentioned.", 'ko': "본문에 '걸어서 10분쯤 걸립니다'라고 쓰여 있어서 걸어서 간다는 것을 알 수 있습니다.", 'ja': "この文章には「歩いて10分ほどかかります」とあり、その人が徒歩で移動することを示しています。バス、地下鉄、自転車については言及されていません。", 'zh': "该段落提到“步行约需10分钟”，表明此人是在步行。文中未提及公交车、地铁和自行车。", 'zh_TW': "這段文字提到「步行約需10分鐘」，表示該人是以步行方式前往。文中並未提及公車、地鐵或自行車。", 'es': "El texto dice «걸어서 10분쯤 걸립니다» (se tarda unos 10 minutos a pie), lo que indica que la persona va andando. No se mencionan el autobús, el metro ni la bicicleta.", 'fr': "Le texte indique « 걸어서 10분쯤 걸립니다 » (cela prend environ 10 minutes à pied), ce qui signifie que la personne se déplace à pied. Le bus, le métro et le vélo ne sont pas mentionnés.", 'de': "In dem Text heißt es: „걸어서 10분쯤 걸립니다“ (zu Fuß dauert es etwa 10 Minuten), was darauf hindeutet, dass die Person zu Fuß geht. Bus, U-Bahn und Fahrrad werden nicht erwähnt."})),
      MockQuestion(id: "ko_topik1_mock_q017", section: "reading", type: MockQuestionType.multiple_choice, question: "어제는 무슨 날이었습니까?", questionEn: "What day was yesterday?", correctAnswer: "생일", distractors: const ["설날", "크리스마스", "추석"], explanation: const LocalizedText({'en': "The passage begins with 어제는 제 생일이었습니다 (Yesterday was my birthday). 설날 = Lunar New Year, 크리스마스 = Christmas, 추석 = Chuseok — none are mentioned.", 'ko': "첫 문장에 '어제는 제 생일이었습니다'라고 명확히 나와 있습니다.", 'ja': "この文章は「昨日は私の誕生日でした」という言葉で始まります。旧正月＝Lunar New Year、クリスマス＝Christmas、秋夕＝Chuseok――これらについては一切触れられていません。", 'zh': "这段文字开头写道：“昨天是我的生日”。春节、圣诞节、中秋节——这些节日都没有被提及。", 'zh_TW': "這段文字以「昨天是我的生日」開頭。春節＝農曆新年、聖誕節＝Christmas、中秋節＝Chuseok——文中均未提及。", 'es': "El texto comienza con «Ayer fue mi cumpleaños». El Año Nuevo Lunar, la Navidad y el Chuseok no se mencionan.", 'fr': "Le passage commence par « Hier, c'était mon anniversaire ». Le Nouvel An lunaire, Noël et Chuseok ne sont pas mentionnés.", 'de': "Der Text beginnt mit „Gestern war mein Geburtstag“. Neujahr = Lunar New Year, Weihnachten = Christmas, Chuseok = Chuseok – keines davon wird erwähnt."})),
      MockQuestion(id: "ko_topik1_mock_q018", section: "reading", type: MockQuestionType.multiple_choice, question: "회사에 몇 시까지 도착합니까?", questionEn: "By what time does the person arrive at the office?", correctAnswer: "9시", distractors: const ["7시", "8시", "6시"], explanation: const LocalizedText({'en': "The passage says 회사에 9시까지 도착합니다 (arrive at the office by 9). 7시 = wake up, 8시 = leave home, 6시 = leave work.", 'ko': "본문에 '회사에 9시까지 도착합니다'라고 쓰여 있습니다.", 'ja': "この文章には「9時までに会社に着きます」と書かれています。7時＝起床、8時＝家を出る、6時＝仕事を終える。", 'zh': "该段落提到“9点前到达公司”。7点 = 起床，8点 = 出门，6点 = 下班。", 'zh_TW': "這段文字提到「9點前抵達公司」。7點 = 起床，8點 = 出門，6點 = 下班。", 'es': "El texto dice: «Llego a la oficina a las 9». 7:00 = me levanto, 8:00 = salgo de casa, 18:00 = salgo del trabajo.", 'fr': "Le passage indique : « J'arrive au bureau à 9 heures ». 7 heures = réveil, 8 heures = départ de chez moi, 18 heures = fin de travail.", 'de': "In dem Text heißt es: „Ich bin um 9 Uhr im Büro“ (arrive at the office by 9). 7 Uhr = aufstehen, 8 Uhr = das Haus verlassen, 18 Uhr = Feierabend."})),
      MockQuestion(id: "ko_topik1_mock_q019", section: "reading", type: MockQuestionType.multiple_choice, question: "왜 두꺼운 옷을 입습니까?", questionEn: "Why does the person wear thick clothes?", correctAnswer: "날씨가 춥기 때문에", distractors: const ["날씨가 덥기 때문에", "옷이 예쁘기 때문에", "친구를 만나기 때문에"], explanation: const LocalizedText({'en': "The passage begins with 요즘 날씨가 아주 춥습니다 (These days the weather is very cold) and uses 그래서 (so/therefore) to connect to wearing thick clothes. This is a clear cause-effect relationship.", 'ko': "'날씨가 아주 춥습니다. 그래서 두꺼운 옷을 입고 다닙니다'라고 인과관계가 명확하게 나타나 있습니다.", 'ja': "この文章は「最近、とても寒いです」という文で始まり、「だから」を使って厚着をするという内容へとつながっています。これは明確な因果関係です。", 'zh': "这段话以“最近天气非常冷”开头，并用“所以”来引出“穿厚衣服”这一内容。这是一种明显的因果关系。", 'zh_TW': "這段文字以「最近天氣非常冷」開頭，並使用「所以」來銜接「穿厚衣服」這個動作。這是一個明確的因果關係。", 'es': "El fragmento comienza con «요즘 날씨가 아주 춥습니다» (Estos días hace mucho frío) y utiliza «그래서» (por eso/por lo tanto) para establecer la conexión con el hecho de llevar ropa de abrigo. Se trata de una clara relación de causa y efecto.", 'fr': "Le passage commence par « Ces jours-ci, il fait très froid » et utilise « donc » pour faire le lien avec le fait de porter des vêtements chauds. Il s'agit là d'une relation de cause à effet évidente.", 'de': "Der Text beginnt mit „요즈음 날씨가 아주 춥습니다“ (In diesen Tagen ist es sehr kalt) und verwendet „그래서“ (also/deshalb), um den Zusammenhang mit dem Tragen warmer Kleidung herzustellen. Dies ist ein klarer Zusammenhang zwischen Ursache und Wirkung."})),
      MockQuestion(id: "ko_topik1_mock_q020", section: "reading", type: MockQuestionType.multiple_choice, question: "왜 영화를 볼 수 없었습니까?", questionEn: "Why couldn't they watch the movie?", correctAnswer: "표가 다 팔려서", distractors: const ["시간이 없어서", "친구가 안 와서", "영화가 재미없어서"], explanation: const LocalizedText({'en': "The passage states 표가 다 팔려서 영화를 볼 수 없었습니다 (tickets were all sold out so we couldn't watch the movie). This is a direct cause-effect statement.", 'ko': "본문에 '표가 다 팔려서 영화를 볼 수 없었습니다'라고 명확히 이유가 나와 있습니다.", 'ja': "この文章には「チケットが完売していたため、映画を見ることができませんでした」とあります。これは直接的な因果関係の記述です。", 'zh': "该段落写道：“票已经卖光了，所以我们没能看成电影。”这是一句直接的因果陈述。", 'zh_TW': "該段落指出：「票已售罄，因此我們無法觀看電影。」這是一個直接的因果陳述。", 'es': "El texto dice: «Las entradas estaban agotadas, así que no pudimos ver la película». Se trata de una afirmación directa de causa y efecto.", 'fr': "Le passage indique : « Les billets étaient tous vendus, nous n'avons donc pas pu voir le film ». Il s'agit d'une affirmation de type cause-effet.", 'de': "In dem Text heißt es: „Die Karten waren ausverkauft, sodass wir den Film nicht sehen konnten.“ Dies ist eine direkte Ursache-Wirkungs-Aussage."})),
      MockQuestion(id: "ko_topik1_mock_q021", section: "listening", type: MockQuestionType.multiple_choice, question: "수진 씨는 지금 무엇을 하고 있습니까?", questionEn: "What is Sujin doing now?", correctAnswer: "목욕하고 있습니다", distractors: const ["전화하고 있습니다", "자고 있습니다", "공부하고 있습니다"], explanation: const LocalizedText({'en': "B says 수진이는 지금 목욕하고 있어요 (Sujin is taking a bath now). The other activities are not mentioned.", 'ko': "B가 '수진이는 지금 목욕하고 있어요'라고 말했습니다. 목욕 중이기 때문에 전화를 받을 수 없는 상황입니다.", 'ja': "Bは「スジンは今お風呂に入っています」と言っています。その他の活動については触れられていません。", 'zh': "B说：秀珍现在正在洗澡。其他活动没有提及。", 'zh_TW': "B 說：秀珍現在正在洗澡。其他活動則未提及。", 'es': "B dice: «Sujin se está bañando ahora mismo». No se mencionan las demás actividades.", 'fr': "B dit : « Sujin est en train de prendre son bain. » Les autres activités ne sont pas mentionnées.", 'de': "B sagt: „Sujin nimmt gerade ein Bad.“ Die anderen Aktivitäten werden nicht erwähnt."})),
      MockQuestion(id: "ko_topik1_mock_q022", section: "listening", type: MockQuestionType.multiple_choice, question: "사과를 몇 개 샀습니까?", questionEn: "How many apples did the person buy?", correctAnswer: "세 개", distractors: const ["한 개", "두 개", "네 개"], explanation: const LocalizedText({'en': "A says 세 개 주세요 (Please give me three) at the end, after the discount is offered. The negotiation is about the price, but the final purchase is 3 apples.", 'ko': "A가 마지막에 '세 개 주세요'라고 말했습니다. 가격 흥정 후 세 개를 구매했습니다.", 'ja': "Aは、値引きの提案を受けた後、最後に「3つください」と言います。交渉は価格について行われましたが、最終的に購入したのはリンゴ3個です。", 'zh': "A在最后，也就是对方提出折扣后，说了一句“请给我三个”。虽然讨价还价的对象是价格，但最终购买的是3个苹果。", 'zh_TW': "A 在最後，也就是對方提出折扣後，說了「請給我三個」。雖然談判的重點是價格，但最終購買的數量是 3 顆蘋果。", 'es': "A dice «세 개 주세요» (Por favor, deme tres) al final, después de que se le haya ofrecido el descuento. La negociación gira en torno al precio, pero al final se compran tres manzanas.", 'fr': "À la fin, après que la réduction a été proposée, A dit « 세 개 주세요 » (Donnez-m'en trois, s'il vous plaît). La négociation porte sur le prix, mais l'achat final porte sur trois pommes.", 'de': "A sagt am Ende, nachdem der Rabatt angeboten wurde: „세 개 주세요“ (Bitte geben Sie mir drei). Bei der Verhandlung geht es um den Preis, aber letztendlich werden drei Äpfel gekauft."})),
      MockQuestion(id: "ko_topik1_mock_q023", section: "listening", type: MockQuestionType.multiple_choice, question: "언제 등산을 가기로 했습니까?", questionEn: "When did they decide to go hiking?", correctAnswer: "일요일", distractors: const ["토요일", "금요일", "월요일"], explanation: const LocalizedText({'en': "B declines Saturday due to a prior appointment, but agrees to Sunday (일요일은 괜찮아요 = Sunday is fine). They settle on 8 AM Sunday.", 'ko': "B가 토요일 약속을 이유로 거절했지만 일요일을 수락했습니다. '일요일은 괜찮아요'라고 대답했습니다.", 'ja': "Bは土曜日は予定があるため断ったが、日曜日は「日曜日は大丈夫です」と承諾した。二人は日曜日の午前8時に決まった。", 'zh': "B 因有事先安排而婉拒了周六的提议，但同意周日（일요일은 괜찮아요 = 周日没问题）。他们最终定在周日早上8点。", 'zh_TW': "B 因有事先約而婉拒週六，但同意週日（「週日沒問題」）。雙方最終定於週日早上 8 點。", 'es': "B rechaza el sábado porque tiene un compromiso previo, pero acepta el domingo («일요일은 괜찮아요» = «El domingo me viene bien»). Quedan en las 8 de la mañana del domingo.", 'fr': "B refuse le samedi car il a déjà un engagement, mais accepte le dimanche (일요일은 괜찮아요 = Le dimanche, ça me va). Ils se mettent d'accord sur dimanche à 8 heures du matin.", 'de': "B lehnt den Samstag wegen eines vorherigen Termins ab, stimmt aber dem Sonntag zu (일요일은 괜찮아요 = Sonntag passt). Sie einigen sich auf Sonntag um 8 Uhr morgens."})),
      MockQuestion(id: "ko_topik1_mock_q024", section: "listening", type: MockQuestionType.multiple_choice, question: "약국까지 얼마나 걸립니까?", questionEn: "How long does it take to the pharmacy?", correctAnswer: "5분", distractors: const ["1분", "10분", "15분"], explanation: const LocalizedText({'en': "B says 5분쯤 걸으면 돼요 (it's about a 5-minute walk). The other times are not mentioned.", 'ko': "B가 '5분쯤 걸으면 돼요'라고 말했습니다.", 'ja': "Bは「5分ほど歩けば着きます」と言っています。それ以外の時間は言及されていません。", 'zh': "B说“走5分钟左右就到了”。其他时间没有提及。", 'zh_TW': "B 說：「走個 5 分鐘左右就到了。」其他時間則未提及。", 'es': "B dice que se tarda unos 5 minutos andando. No se mencionan los demás tiempos.", 'fr': "B dit : « C'est à environ 5 minutes à pied. » Les autres durées ne sont pas mentionnées.", 'de': "B sagt: „Das sind etwa 5 Minuten zu Fuß.“ Die anderen Zeiten werden nicht erwähnt."})),
      MockQuestion(id: "ko_topik1_mock_q025", section: "listening", type: MockQuestionType.multiple_choice, question: "어제 무엇을 샀습니까?", questionEn: "What did the person buy yesterday?", correctAnswer: "가방", distractors: const ["구두", "모자", "시계"], explanation: const LocalizedText({'en': "B says 가방을 하나 샀어요 (I bought a bag). The follow-up describes it as a black, small but practical bag. 구두 = shoes, 모자 = hat, 시계 = watch — none are mentioned.", 'ko': "B가 '가방을 하나 샀어요'라고 말했고, 이어서 가방에 대한 설명을 했습니다.", 'ja': "Bは「バッグを一つ買いました」と言っています。その後の説明によると、それは黒で、小さいけれど実用的なバッグだそうです。靴、帽子、時計については、いずれも言及されていません。", 'zh': "B说：“我买了一个包。”后续描述中提到，这是一个黑色、小巧但实用的包。鞋子、帽子、手表——这些都没有提到。", 'zh_TW': "B 說：「我買了一個包包。」後續描述中提到，那是一個黑色、小巧但實用的包包。鞋子、帽子、手錶——這些都沒有被提及。", 'es': "B dice: «Me he comprado un bolso». A continuación, lo describe como un bolso negro, pequeño pero práctico. Zapatos, sombrero, reloj: no se menciona ninguno de ellos.", 'fr': "B dit : « J'ai acheté un sac ». La suite précise qu'il s'agit d'un petit sac noir, mais pratique. Chaussures, chapeau, montre : aucun de ces objets n'est mentionné.", 'de': "B sagt: „가방을 하나 샀어요“ (Ich habe eine Tasche gekauft). Im weiteren Verlauf wird sie als schwarze, kleine, aber praktische Tasche beschrieben. 구두 = Schuhe, 모자 = Hut, 시계 = Uhr – nichts davon wird erwähnt."})),
    ],
  );
  static final MockTest jlptN5 = MockTest(
    examName: "JLPT N5",
    language: "ja",
    sections: const [
      MockSection(sectionId: "vocab_mc", title: "語彙 — 多肢選択 (Vocabulary — Multiple Choice)", count: 10),
      MockSection(sectionId: "grammar_fib", title: "文法 — 穴埋め (Grammar — Fill in the Blank)", count: 5),
      MockSection(sectionId: "reading", title: "読解 (Reading Comprehension)", count: 5),
      MockSection(sectionId: "listening", title: "聴解 (Listening — text-based)", count: 5),
    ],
    questions: const [
      MockQuestion(id: "ja_n5_mock_q001", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「わたしは まいにち がっこうに ＿＿＿。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'I ___ to school every day.'?", correctAnswer: "いきます", distractors: const ["かえります", "ねます", "みます"], explanation: const LocalizedText({'en': "行きます (いきます) means 'to go'. The sentence means 'I go to school every day.' 帰ります (かえります) = return home, 寝ます (ねます) = sleep, 見ます (みます) = see/watch. Only 行きます makes sense with 学校に (to school).", 'ko': "'行きます(이쿠마스)'는 '가다'라는 뜻입니다. 이 문장은 '나는 매일 학교에 간다'라는 의미입니다. '帰ります(카에마스)' = 집에 돌아오다, '寝ます(네마스)' = 자다, '見ます(미마스)' = 보다/지다. '学校に(학교에)'와 어울리는 것은 '行きます'뿐입니다.", 'ja': "「行きます」は「go」の意味です。学校に行くという表現が自然です。", 'zh': "“行きます”意为“去”。该句的意思是“我每天去学校”。“帰ります”=回家，“寝ます”=睡觉，“見ます”=看。只有“行きます”与“学校に”（去学校）搭配才通顺。", 'zh_TW': "「行きます」意為「去」。這句話的意思是「我每天都去上學」。歸ります（回家）、寝ます（睡覺）、見ます（看）。只有「行きます」搭配「学校に」（去學校）才合乎語意。", 'es': "«行きます» significa «ir». La frase significa «Voy al colegio todos los días». «帰ります» = volver a casa, «寝ます» = dormir, «見ます» = ver/mirar. Solo «行きます» tiene sentido con «学校に» (al colegio).", 'fr': "« 行きます » (ikimasu) signifie « aller ». La phrase signifie « Je vais à l'école tous les jours ». « 帰ります » (kaerimasu) = rentrer chez soi, « 寝ます » (nemasu) = dormir, « 見ます » (mimasu) = voir/regarder. Seul « 行きます » a du sens avec « 学校に » (à l'école).", 'de': "„行きます“ (ikimasu) bedeutet „gehen“. Der Satz bedeutet „Ich gehe jeden Tag zur Schule.“ „帰ります“ (kaerimasu) = nach Hause gehen, „寝ます“ (nemasu) = schlafen, „見ます“ (mimasu) = sehen/anschauen. Nur „行きます“ passt zu „学校に“ (zur Schule)."})),
      MockQuestion(id: "ja_n5_mock_q002", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「きょうは てんきが ＿＿＿です。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'The weather is ___ today.'?", correctAnswer: "いい", distractors: const ["おおきい", "たかい", "あたらしい"], explanation: const LocalizedText({'en': "いい means 'good'. 天気がいい is the standard Japanese expression for 'the weather is good'. 大きい = big, 高い = expensive/tall, 新しい = new. None of these describe weather naturally.", 'ko': "'いい'는 '좋다'라는 뜻입니다. '天気がいい'는 '날씨가 좋다'를 뜻하는 표준 일본어 표현입니다. 大きい = 크다, 高い = 비싸다/키가 크다, 新しい = 새롭다. 이 단어들은 날씨를 자연스럽게 묘사하는 표현이 아닙니다.", 'ja': "「いい」は「good」の意味です。「天気がいい」は天候を表す自然な表現です。", 'zh': "“いい”的意思是“好”。“天気がいい”是日语中表示“天气好”的标准说法。大きい = 大，高い = 贵/高，新しい = 新。这些词语都不自然地用来描述天气。", 'zh_TW': "「いい」的意思是「好」。「天気がいい」是日語中表示「天氣很好」的標準說法。大きい = 大，高い = 貴／高，新しい = 新。這些詞彙都無法自然地用來描述天氣。", 'es': "«いい» significa «bueno». «天気がいい» es la expresión estándar en japonés para decir «hace buen tiempo». 大きい = grande, 高い = caro/alto, 新しい = nuevo. Ninguna de estas palabras describe el tiempo de forma natural.", 'fr': "« いい » signifie « bien ». « 天気がいい » est l'expression japonaise standard pour dire « il fait beau ». 大きい = grand, 高い = cher/grand, 新しい = neuf. Aucun de ces mots ne décrit naturellement le temps qu'il fait.", 'de': "„いい“ bedeutet „gut“. „天気がいい“ ist die übliche japanische Redewendung für „das Wetter ist gut“. „大きい“ = groß, „高い“ = teuer/hoch, „新しい“ = neu. Keines dieser Wörter beschreibt das Wetter auf natürliche Weise."})),
      MockQuestion(id: "ja_n5_mock_q003", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「きのう ともだちに ＿＿＿。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'I ___ a friend yesterday.'?", correctAnswer: "あいました", distractors: const ["みました", "かきました", "ききました"], explanation: const LocalizedText({'en': "会いました (あいました) means 'met'. 友達に会う = to meet a friend. 見ました = saw, 書きました = wrote, 聞きました = heard/asked. Only 会いました fits with 友達に.", 'ko': "'会いました(아이미타)'는 '만났다'라는 뜻입니다. 친구를 만나다 = to meet a friend. 보았다 = saw, 썼다 = wrote, 들었다 = heard/asked. 오직 '会いました'만이 '友達に'와 어울립니다.", 'ja': "「会いました」は「met」の意味です。「友達に会う」は「友達と会う」という自然な表現です。", 'zh': "“会いました”意为“见面”。“友達に会う”即“见到朋友”。“見ました”意为“看到”，“書きました”意为“写了”，“聞きました”意为“听到/问了”。只有“会いました”与“友達に”搭配使用。", 'zh_TW': "「会いました」意為「見到」。見到朋友 = 見到朋友。見ました = 看見，書きました = 寫了，聞きました = 聽見／問了。只有「会いました」能與「友達に」搭配使用。", 'es': "«会いました» significa «me encontré con». «友達に会う» = «encontrarse con un amigo». «見ました» = «vi», «書きました» = «escribí», «聞きました» = «oí/pregunté». Solo «会いました» encaja con «友達に».", 'fr': "「会いました» signifie «rencontré». «友達に会う» = «rencontrer un ami». «見ました» = «vu», «書きました» = «écrit», «聞きました» = «entendu/demandé». Seul «会いました» va avec «友達に».", 'de': "„会いました“ (aimashita) bedeutet „getroffen“. 友達に会う = einen Freund treffen. 見ました = gesehen, 書きました = geschrieben, 聞きました = gehört/gefragt. Nur „会いました“ passt zu „友達に“."})),
      MockQuestion(id: "ja_n5_mock_q004", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「この りんごは とても ＿＿＿です。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'This apple is very ___ .'?", correctAnswer: "あまい", distractors: const ["からい", "しおからい", "にがい"], explanation: const LocalizedText({'en': "甘い (あまい) means 'sweet'. Apples are sweet. 辛い (からい) = spicy, 塩辛い (しおからい) = salty, 苦い (にがい) = bitter. Only 甘い describes an apple naturally.", 'ko': "'甘い(아마이)'는 '달다'라는 뜻입니다. 사과는 달습니다. '辛い(카라이)'는 매운 맛, '塩辛い(시오카라이)'는 짠 맛, '苦い(니가이)'는 쓴 맛을 뜻합니다. 사과를 자연스럽게 묘사할 때는 오직 '甘い'만 사용됩니다.", 'ja': "「甘い」は「sweet」の意味です。りんごの味を表すのに最も適切です。", 'zh': "“甘い (あまい)”意为“甜”。苹果是甜的。“辛い (からい)”= 辣，“塩辛い (しおからい)”= 咸，“苦い (にがい)”= 苦。只有“甘い”能自然地形容苹果。", 'zh_TW': "「甘い (あまい)」意為「甜」。蘋果是甜的。「辛い (からい)」＝辣、「塩辛い (しおからい)」＝鹹、「苦い (にがい)」＝苦。只有「甘い」能自然地形容蘋果。", 'es': "「甘い (amai)» significa «dulce». Las manzanas son dulces. 「辛い (karai)» = picante, 「塩辛い (shiokarai)» = salado, 「苦い (nagai)» = amargo. Solo 「甘い」 describe de forma natural a una manzana.", 'fr': "「甘い (amai) » signifie « sucré ». Les pommes sont sucrées. « 辛い (karai) » = épicé, « 塩辛い (shiokarai) » = salé, « 苦い (nigai) » = amer. Seul « 甘い » décrit naturellement une pomme.", 'de': "„甘い“ (amai) bedeutet „süß“. Äpfel sind süß. „辛い“ (karai) = scharf, „塩辛い“ (shiokarai) = salzig, „苦い“ (nagai) = bitter. Nur „甘い“ beschreibt einen Apfel auf natürliche Weise."})),
      MockQuestion(id: "ja_n5_mock_q005", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「えきの ＿＿＿に コンビニが あります。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'There is a convenience store ___ the station.'?", correctAnswer: "まえ", distractors: const ["うしろ", "ひだり", "みぎ"], explanation: const LocalizedText({'en': "前 (まえ) means 'in front of'. 駅の前に = in front of the station. 後ろ = behind, 左 = left, 右 = right. All are grammatically possible but 前 is the most common location reference for station-area shops.", 'ko': "'前(마에)'는 '앞'을 의미합니다. 駅の前に = 역 앞. 後ろ = 뒤, 左 = 왼쪽, 右 = 오른쪽. 모두 문법적으로 가능하지만, 역 주변 상점의 위치를 지칭할 때는 '前'가 가장 흔히 사용됩니다.", 'ja': "「前」は「in front of」の意味です。駅の前にあるという表現が最も一般的です。", 'zh': "“前（まえ）”意为“在……前面”。“駅の前に”即“在车站前面”。“後ろ”意为“后面”，“左”意为“左边”，“右”意为“右边”。这些说法在语法上都是成立的，但“前”是车站周边店铺最常用的方位表述。", 'zh_TW': "「前 (まえ)」意為「在……前面」。車站的前面 = 車站前方。後面 = 後方，左邊 = 左側，右邊 = 右側。這些說法在語法上皆成立，但「前」是車站周邊店家最常用的方位詞。", 'es': "前 (mae) significa «delante de». 駅の前に = delante de la estación. 後ろ = detrás, 左 = izquierda, 右 = derecha. Todas estas expresiones son gramaticalmente correctas, pero 前 es la referencia de ubicación más habitual para las tiendas de la zona de la estación.", 'fr': "前 (mae) signifie « devant ». 駅の前に = devant la gare. 後ろ = derrière, 左 = à gauche, 右 = à droite. Toutes ces expressions sont grammaticalement correctes, mais 前 est la référence spatiale la plus courante pour les commerces situés aux abords de la gare.", 'de': "前 (mae) bedeutet „vor“. 駅の前に = vor dem Bahnhof. 後ろ = hinter, 左 = links, 右 = rechts. Alle sind grammatikalisch möglich, aber 前 ist die gebräuchlichste Ortsangabe für Geschäfte im Bahnhofsbereich."})),
      MockQuestion(id: "ja_n5_mock_q006", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「あには ＿＿＿ せが たかいです。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'My older brother is ___ tall.'?", correctAnswer: "とても", distractors: const ["あまり", "ぜんぜん", "よく"], explanation: const LocalizedText({'en': "とても means 'very'. 背がとても高い = very tall. あまり is used with negatives (あまり〜ない), ぜんぜん is used with negatives (ぜんぜん〜ない), よく = often/well, which doesn't fit describing height.", 'ko': "'とても'는 '매우'라는 뜻입니다. 키가 매우 크다 = very tall. 'あまり'는 부정형(あまり~ない)과 함께 쓰이고, 'ぜんぜん'은 부정형(ぜんぜん~ない)과 함께 쓰이며, 'よく'는 '자주/잘'이라는 뜻으로 키를 묘사하는 데는 맞지 않습니다.", 'ja': "「とても」は「very」の意味です。程度を強調する副詞として適切です。", 'zh': "“とても”意为“非常”。“背がとても高い”即“非常高”。“あまり”用于否定句（あまり〜ない），“ぜんぜん”也用于否定句（ぜんぜん〜ない），“よく”意为“经常/很好”，不适用于描述身高。", 'zh_TW': "「とても」意為「非常」。背很高 = 非常高。「あまり」用於否定句（あまり〜ない）、「ぜんぜん」用於否定句（ぜんぜん〜ない），而「よく」意為「經常／很好」，不適用於描述身高。", 'es': "«とても» significa «muy». «背がとても高い» = «muy alto». «あまり» se usa con negaciones (あまり〜ない), «ぜんぜん» se usa con negaciones (ぜんぜん〜ない), «よく» = «a menudo/bien», lo cual no encaja para describir la altura.", 'fr': "« とても » signifie « très ». « 背がとても高い » = « très grand ». « あまり » s'utilise avec des négations (あまり〜ない), « ぜんぜん » s'utilise avec des négations (ぜんぜん〜ない), « よく » = « souvent/bien », ce qui ne convient pas pour décrire la taille.", 'de': "„とても“ bedeutet „sehr“. „背がとても高い“ = „sehr groß“. „あまり“ wird in Verneinungen verwendet (あまり〜ない), „ぜんぜん“ wird in Verneinungen verwendet (ぜんぜん〜ない), „よく“ bedeutet „oft“ oder „gut“, was nicht zur Beschreibung der Körpergröße passt."})),
      MockQuestion(id: "ja_n5_mock_q007", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「つめたい ＿＿＿ を のみたいです。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'I want to drink cold ___ .'?", correctAnswer: "みず", distractors: const ["ごはん", "パン", "にく"], explanation: const LocalizedText({'en': "水 (みず) means 'water'. 冷たい水 = cold water, and you drink (飲む) water. ごはん = rice/meal, パン = bread, 肉 = meat — none of these are typically drunk (飲む).", 'ko': "'水(미즈)'는 '물'을 뜻합니다. '冷たい水'는 '찬물'을 의미하며, 물은 '마신다(飲む)'고 합니다. 'ごはん'은 '밥', 'パン'은 '빵', '肉'은 '고기'를 뜻하는데, 이 단어들은 일반적으로 '마신다(飲む)'고 표현하지 않습니다.", 'ja': "「水」は「water」です。飲む対象として正しく、冷たい水は自然な表現です。", 'zh': "“水 (みず)”的意思是“水”。“冷たい水”=冷水，而“水”是用来喝的（飲む）。“ごはん”=米饭/饭，“パン”=面包，“肉”=肉——这些通常都不喝（飲む）。", 'zh_TW': "「水 (みず)」的意思是「水」。「冷たい水」＝冷水，而「水」是拿來喝的（飲む）。「ごはん」＝米飯／餐點、「パン」＝麵包、「肉」＝肉——這些通常都不會被「喝」（飲む）。", 'es': "水 (mizu) significa «agua». 冷たい水 = agua fría, y el agua se bebe (nomu). ごはん = arroz/comida, パン = pan, 肉 = carne; ninguno de estos alimentos se suele beber (nomu).", 'fr': "水 (mizu) signifie « eau ». 冷たい水 = eau froide, et on boit (飲む) de l'eau. ごはん = riz/repas, パン = pain, 肉 = viande — aucun de ces aliments n'est généralement bu (飲む).", 'de': "水 (mizu) bedeutet „Wasser“. 冷たい水 = kaltes Wasser, und man trinkt (飲む) Wasser. ごはん = Reis/Mahlzeit, パン = Brot, 肉 = Fleisch – nichts davon wird normalerweise getrunken (飲む)."})),
      MockQuestion(id: "ja_n5_mock_q008", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「まいばん おふろに ＿＿＿。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'I ___ a bath every night.'?", correctAnswer: "はいります", distractors: const ["でます", "おきます", "すわります"], explanation: const LocalizedText({'en': "入ります (はいります) means 'to enter'. お風呂に入る = to take a bath (lit. enter the bath). 出ます = exit, 起きます = wake up, 座ります = sit. Only 入ります collocates with お風呂.", 'ko': "'入ります(하이리마스)'는 '들어가다'라는 뜻입니다. お風呂に入る = 목욕하다 (직역: 욕조에 들어가다). 出ます = 나가다, 起きます = 일어나다, 座ります = 앉다. 오직 '入ります'만이 'お風呂'와 함께 쓰입니다.", 'ja': "「入ります」は「enter」の意味です。「お風呂に入る」は入浴するという自然な表現です。", 'zh': "“入ります”意为“进入”。“お風呂に入る”= 洗澡（字面意思是“进入浴缸”）。“出ます”= 出去，“起きます”= 起床，“座ります”= 坐下。只有“入ります”与“お風呂”搭配使用。", 'zh_TW': "「入ります」意為「進入」。入浴 = 洗澡（字面意思是進入浴缸）。出ます = 出去，起きます = 起床，座ります = 坐下。只有「入ります」會與「お風呂」搭配使用。", 'es': "「入ります (ha-ri-masu)» significa «entrar». «お風呂に入る» = darse un baño (lit. entrar en la bañera). «出ます» = salir, «起きます» = levantarse, «座ります» = sentarse. Solo «入ります» se utiliza con «お風呂».", 'fr': "« 入ります » (ha-ri-masu) signifie « entrer ». « お風呂に入る » = prendre un bain (littéralement : entrer dans le bain). « 出ます » = sortir, « 起きます » = se réveiller, « 座ります » = s'asseoir. Seul « 入ります » s'utilise avec « お風呂 ».", 'de': "„入ります“ (ha-iru) bedeutet „eingehen“. „お風呂に入る“ = ein Bad nehmen (wörtlich: in die Badewanne gehen). „出ます“ = hinausgehen, „起きます“ = aufwachen, „座ります“ = sich hinsetzen. Nur „入ります“ wird mit „お風呂“ verwendet."})),
      MockQuestion(id: "ja_n5_mock_q009", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「つくえの うえに ほんが ＿＿＿。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'There ___ a book on the desk.'?", correctAnswer: "あります", distractors: const ["います", "します", "なります"], explanation: const LocalizedText({'en': "あります is used for inanimate objects (books). います is for living beings, します = do, なります = become. Since a book is inanimate, あります is correct.", 'ko': "'あります'는 무생물(책)에 사용됩니다. 'います'는 생물에게 쓰이며, 'します'는 '~하다', 'なります'는 '~되다'를 의미합니다. 책은 무생물이므로 'あります'가 맞습니다.", 'ja': "「あります」は無生物の存在を表します。本は生き物ではないので「あります」が正しいです。", 'zh': "“あります”用于指代非生物（如书籍）。“います”用于指代生物，“します”表示“做”，“なります”表示“变成”。由于书是无生命的，因此“あります”是正确的。", 'zh_TW': "「あります」用於無生命的事物（如書籍）。「います」用於生物，「します」表示「做」，「なります」表示「變成」。由於書籍是無生命的，因此使用「あります」是正確的。", 'es': "«あります» se utiliza para objetos inanimados (libros). «います» se utiliza para seres vivos; «します» significa «hacer» y «なります» significa «convertirse». Dado que un libro es inanimado, lo correcto es «あります».", 'fr': "« あります » s'utilise pour les objets inanimés (les livres). « います » s'utilise pour les êtres vivants, « します » signifie « faire » et « なります » signifie « devenir ». Comme un livre est un objet inanimé, « あります » est la forme correcte.", 'de': "„あります“ wird für unbelebte Gegenstände (Bücher) verwendet. „います“ gilt für Lebewesen, „します“ bedeutet „tun“ und „なります“ bedeutet „werden“. Da ein Buch unbelebt ist, ist „あります“ die richtige Form."})),
      MockQuestion(id: "ja_n5_mock_q010", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「わたしの へやは ＿＿＿です。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'My room is ___ .'?", correctAnswer: "ひろい", distractors: const ["あつい", "はやい", "ちかい"], explanation: const LocalizedText({'en': "広い (ひろい) means 'spacious/wide'. Used for rooms and spaces. 暑い = hot (weather), 速い = fast, 近い = near. Only 広い naturally describes a room.", 'ko': "'넓다(ひろい)'는 '넓은'이라는 뜻입니다. 방이나 공간을 가리킬 때 씁니다. '덥다(暑い)'는 날씨가 덥다는 뜻이고, '빠르다(速い)'는 속도가 빠르다는 뜻이며, '가깝다(近い)'는 거리가 가깝다는 뜻입니다. 방을 묘사할 때는 오직 '넓다'만이 자연스럽게 쓰입니다.", 'ja': "「広い」は「spacious」の意味です。部屋の広さを表すのに最も適切な形容詞です。", 'zh': "“広い (hiroi)”意为“宽敞/宽阔”。用于描述房间和空间。 “暑い”= 热（天气），“速い”= 快，“近い”= 近。只有“広い”自然用于描述房间。", 'zh_TW': "「広い (hiroi)」意為「寬敞／寬闊」。常用來形容房間和空間。 「暑い」＝熱（天氣）、「速い」＝快、「近い」＝近。只有「広い」自然會用來形容房間。", 'es': "«Hiroi» significa «espacioso/amplio». Se utiliza para habitaciones y espacios. «Atsui» = calor (clima), «hayai» = rápido, «chikai» = cerca. Solo «hiroi» describe de forma natural una habitación.", 'fr': "« 広い (hiroi) » signifie « spacieux/vaste ». Ce terme s'utilise pour les pièces et les espaces. « 暑い » = chaud (temps), « 速い » = rapide, « 近い » = proche. Seul « 広い » décrit naturellement une pièce.", 'de': "„Hiroi“ bedeutet „geräumig/weit“. Wird für Räume und Flächen verwendet. „Atsui“ = heiß (Wetter), „Hayai“ = schnell, „Chikai“ = nah. Nur „Hiroi“ beschreibt auf natürliche Weise einen Raum."})),
      MockQuestion(id: "ja_n5_mock_q011", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "あした とうきょうに ＿＿＿ つもりです。 (いきます / いく)", questionEn: "Fill in the blank: 'I intend to ___ to Tokyo tomorrow.' (go)", correctAnswer: "いく", distractors: const ["いきます", "いった", "いかない"], explanation: const LocalizedText({'en': "〜つもりです requires the dictionary (plain) form of the verb before it. いく is the dictionary form. いきます is the polite form and cannot be used before つもり. The pattern is: Verb (dictionary form) + つもりです = intend to do.", 'ko': "〜つもりです 앞에는 동사의 기본형(사전형)이 와야 합니다. いく는 기본형입니다. いきます는 정중형으로, つもり 앞에서는 사용할 수 없습니다. 문법 구조는 다음과 같습니다: 동사(기본형) + つもりです = ~할 생각입니다.", 'ja': "「〜つもりです」の前には動詞の辞書形（普通形）を使います。「いく」が辞書形で、「いきます」は丁寧形なので使えません。", 'zh': "〜つもりです 前面必须是动词的词典（原形）形式。いく 是词典形式。いきます 是敬语形式，不能用于 つもり 之前。该句型为：动词（词典形式）＋ つもりです ＝ 打算做。", 'zh_TW': "〜つもりです 前面必須接動詞的字典形（基本形）。いく 是字典形。いきます 是敬語形式，不能用在 つもり 之前。其句型為：動詞（字典形）＋ つもりです ＝ 打算做。", 'es': "«〜つもりです» requiere que el verbo que le precede esté en forma básica (de diccionario). «いく» es la forma básica. «いきます» es la forma cortés y no se puede usar antes de «つもり». La estructura es: Verbo (forma básica) + つもりです = tengo la intención de hacer.", 'fr': "〜つもりです s'utilise avec la forme de base (standard) du verbe qui le précède. いく est la forme de base. いきます est la forme polie et ne peut pas être utilisée avant つもり. La structure est la suivante : Verbe (forme de base) + つもりです = avoir l'intention de faire.", 'de': "Vor „〜つもりです“ muss die Grundform des Verbs stehen. „いく“ ist die Grundform. „いきます“ ist die höfliche Form und kann nicht vor „つもり“ verwendet werden. Das Muster lautet: Verb (Grundform) + つもりです = beabsichtigen, etwas zu tun."})),
      MockQuestion(id: "ja_n5_mock_q012", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "ここで しゃしんを ＿＿＿ ないでください。 (とる / とります)", questionEn: "Fill in the blank: 'Please don't ___ photos here.' (take)", correctAnswer: "とら", distractors: const ["とります", "とった", "とる"], explanation: const LocalizedText({'en': "〜ないでください requires the ない-form (plain negative stem) before でください. The verb 撮る (とる) becomes とらない in plain negative, and the ない-form stem is とら. Pattern: Verb ない-form + でください = Please don't do.", 'ko': "~ないでください는 でください 앞에 ない-형(부정형 어간)이 와야 합니다. 동사 撮る(토루)는 부정형에서 とらない가 되며, ない-형 어간은 と라입니다. 패턴: 동사 ない-형 + でください = ~하지 마세요.", 'ja': "「〜ないでください」の前には動詞のナイ形が必要です。「とる」のナイ形は「とらない」で、「とら」の部分を使います。", 'zh': "“〜ないでください”需要在“でください”之前使用“ない”形（普通否定词干）。动词“撮る”（toru）的普通否定形式为“とらない”，其“ない”形词干为“とら”。句式：动词“ない”形 + でください = 请不要……", 'zh_TW': "〜ないでください 需要在 でください 之前加上 ない-形（普通否定詞幹）。動詞 撮る (とる) 的普通否定形式為 とらない，其 ない-形詞幹為 とら。句型：動詞 ない-形 + でください = 請不要做。", 'es': "La expresión «〜ないでください» requiere la forma «nai» (raíz negativa simple) antes de «でください». El verbo «撮る» (toru) se convierte en «とらない» en la forma negativa simple, y la raíz de la forma «nai» es «とら». Patrón: Verbo + forma «nai» + でください = Por favor, no hagas...", 'fr': "« ~ないでください » nécessite la forme « ない » (radical négatif simple) avant « でください ». Le verbe 撮る (toru) devient とらない à la forme négative simple, et le radical de la forme « ない » est とら. Modèle : forme « ない » du verbe + でください = « S'il vous plaît, ne faites pas ».", 'de': "„〜ないでください“ erfordert die „ない“-Form (Negativstamm) vor „でください“. Das Verb „撮る“ (toru) wird im Negativ zu „とらない“, und der Stamm der „ない“-Form lautet „とら“. Muster: Verb in der „ない“-Form + „でください“ = Bitte nicht tun."})),
      MockQuestion(id: "ja_n5_mock_q013", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "きのう すしを ＿＿＿ ことがあります。 (たべる / たべます)", questionEn: "Fill in the blank: 'I have ___ sushi before.' (eat)", correctAnswer: "たべた", distractors: const ["たべる", "たべます", "たべない"], explanation: const LocalizedText({'en': "〜たことがある requires the た-form (plain past) before ことがある. 食べた is the plain past of 食べる. This grammar expresses experience: Verb た-form + ことがある = have done before.", 'ko': "~たことがある는 ことがある 앞에 た-형(단순 과거형)이 와야 합니다. 食べた는 食べる의 단순 과거형입니다. 이 문법은 경험을 나타냅니다: 동사 た-형 + ことがある = 이전에 ~한 적이 있다.", 'ja': "「〜たことがある」の前には動詞のタ形（普通過去形）を使います。経験を表す文法です。", 'zh': "“〜たことがある”需要在“ことがある”之前使用“た”形（普通过去式）。“食べた”是“食べる”的普通过去式。这种语法表达的是经验：动词“た”形 + “ことがある” = 曾经做过。", 'zh_TW': "「〜たことがある」需要在「ことがある」之前加上「た」形（普通過去式）。「食べた」是「食べる」的普通過去式。這種語法表達「曾經做過」的意思：動詞「た」形 + 「ことがある」= 曾經做過。", 'es': "La expresión «〜たことがある» requiere la forma «た» (pasado simple) antes de «ことがある». «食べた» es el pasado simple de «食べる». Esta construcción gramatical expresa experiencia: forma «た» del verbo + «ことがある» = haber hecho algo antes.", 'fr': "Pour former la phrase « 〜たことがある », il faut placer la forme « た » (passé simple) avant « ことがある ». « 食べた » est le passé simple de « 食べる ». Cette construction grammaticale exprime une expérience : forme « た » du verbe + « ことがある » = avoir déjà fait.", 'de': "„〜たことがある“ erfordert die た-Form (einfache Vergangenheit) vor „ことがある“. „食べた“ ist die einfache Vergangenheit von „食べる“. Diese Grammatik drückt Erfahrung aus: Verb in der た-Form + „ことがある“ = schon einmal getan haben."})),
      MockQuestion(id: "ja_n5_mock_q014", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "この ケーキは おいし＿＿＿ です。 (い-adj: おいしい)", questionEn: "Fill in the blank: 'This cake is ___ .' (delicious — polite negative past)", correctAnswer: "くなかった", distractors: const ["くない", "かった", "い"], explanation: const LocalizedText({'en': "For i-adjectives in polite negative past: drop い, add くなかった + です. 美味しい → 美味しくなかったです = was not delicious. 美味しかった = was delicious (positive past), 美味しくない = not delicious (negative present), 美味しい = delicious (positive present).", 'ko': "정중 과거형에서 ‘い’로 끝나는 형용사의 경우: ‘い’를 빼고 ‘くなかった’ + ‘です’를 붙입니다. 美味しい → 美味しくなかったです = 맛있지 않았습니다. 美味しかった = 맛있었습니다 (과거 긍정), 美味しくない = 맛없습니다 (현재 부정), 美味しい = 맛있습니다 (현재 긍정).", 'ja': "い形容詞の丁寧否定過去形は「〜くなかったです」です。「美味しい」→「美味しくなかったです」となります。", 'zh': "对于“い”结尾形容词的敬语过去否定形式：去掉“い”，加上“くなかった”+“です”。美味的 → 美味しくなかったです = 以前并不美味。美味だった = 以前很美味（过去肯定），美味しくない = 不好吃（现在否定），美味しい = 美味（现在肯定）。", 'zh_TW': "關於「い」形容詞的禮貌過去否定形式：去掉「い」，加上「くなかった」＋「です」。美味的 → 美味しくなかったです = 以前不美味。美味だった = 以前美味（過去肯定），美味しくない = 不美味（現在否定），美味しい = 美味（現在肯定）。", 'es': "Para los adjetivos «i» en el pasado negativo cortés: omite «i» y añade «くなかった» + «です». Delicioso → No estaba delicioso = no estaba delicioso. Estaba delicioso = estaba delicioso (pasado afirmativo), No está delicioso = no está delicioso (presente negativo), Delicioso = delicioso (presente afirmativo).", 'fr': "Pour les adjectifs en « i » au passé négatif de politesse : supprimer « i », ajouter « くなかった » + « です ». 美味しい → 美味しくなかったです = n'était pas délicieux. 美味しかった = était délicieux (passé positif), 美味しくない = n'est pas délicieux (présent négatif), 美味しい = délicieux (présent positif).", 'de': "Bei i-Adjektiven in der höflichen Verneinung der Vergangenheit: Das „i“ weglassen, „kunakatta“ + „desu“ hinzufügen. Oishii → Oishikunakatta = war nicht lecker. Oishikatta = war lecker (bejahende Vergangenheit), Oishikunai = nicht lecker (verneinende Gegenwart), Oishii = lecker (bejahende Gegenwart)."})),
      MockQuestion(id: "ja_n5_mock_q015", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "わたしは えいがを ＿＿＿ たいです。 (みる / みます)", questionEn: "Fill in the blank: 'I want to ___ a movie.' (watch)", correctAnswer: "み", distractors: const ["みる", "みます", "みた"], explanation: const LocalizedText({'en': "〜たい attaches to the verb stem (ます-form without ます). 見ます → 見. So 見たい = want to watch. 見る is the dictionary form, which doesn't work with 〜たい directly. Pattern: Verb stem + たい.", 'ko': "〜たい는 동사 어간(‘ます’를 뺀 ‘ます’형)에 붙습니다. 見ます → 見. 따라서 見たい는 ‘보고 싶다’는 뜻입니다. 見る는 사전형으로, 〜たい와 직접 결합할 수 없습니다. 구문: 동사 어간 + たい.", 'ja': "「〜たい」は動詞のます形から「ます」を取った語幹につけます。「見ます」→「見」→「見たい」となります。", 'zh': "〜たい接在动词词干（即去掉“ます”的“ます”形）之后。例如：見ます → 見。因此，見たい = 想看。見る是词典形，不能直接与〜たい搭配使用。句式：动词词干 + たい。", 'zh_TW': "〜たい 接在動詞詞幹上（即「ます」形去掉「ます」後）。見ます → 見。因此 見たい = 想看。見る 是字典形，無法直接與 〜たい 搭配使用。語法模式：動詞詞幹 + たい。", 'es': "〜たい se añade a la raíz del verbo (la forma «mas» sin «mas»). 見ます → 見. Por lo tanto, 見たい = querer ver. 見る es la forma del diccionario, que no se puede combinar directamente con 〜たい. Estructura: raíz del verbo + たい.", 'fr': "〜たい se rajoute au radical du verbe (forme en -ます sans le ます). 見ます → 見. Ainsi, 見たい = vouloir regarder. 見る est la forme du dictionnaire, qui ne s'utilise pas directement avec 〜たい. Structure : radical du verbe + たい.", 'de': "〜たい wird an den Verbstamm angehängt (Masu-Form ohne ます). 見ます → 見. Also 見たい = sehen wollen. 見る ist die Grundform, die nicht direkt mit 〜たい kombiniert werden kann. Muster: Verbstamm + たい."})),
      MockQuestion(id: "ja_n5_mock_q016", section: "reading", type: MockQuestionType.multiple_choice, question: "おかあさんは どこで はたらいていますか。", questionEn: "Where does the mother work?", correctAnswer: "びょういん", distractors: const ["かいしゃ", "だいがく", "こうこう"], explanation: const LocalizedText({'en': "The passage says ははは びょういんで はたらいています (Mother works at a hospital). かいしゃ = company (father), だいがく = university (brother), こうこう = high school (the speaker).", 'ko': "이 문장은 “하하하, 엄마는 병원에서 일하고 계세요”라고 말합니다. 회사 = 회사(아버지), 대학 = 대학(오빠), 고등학교 = 고등학교(화자).", 'ja': "文中に「ははは びょういんで はたらいています」と書かれています。", 'zh': "文中提到“哈哈哈，妈妈在医院工作”。“公司”指父亲，“大学”指哥哥，“高中”指说话者本人。", 'zh_TW': "這段文字提到「哈哈哈，媽媽在醫院工作」。公司＝公司（父親）、大學＝大學（哥哥）、高中＝高中（說話者）。", 'es': "El texto dice: «Ja, ja, mi madre trabaja en un hospital». «Kaisha» = empresa (el padre), «daigaku» = universidad (el hermano), «kōkō» = instituto (el narrador).", 'fr': "Le passage dit : « Ha ha ha, ma mère travaille à l'hôpital. » Entreprise = entreprise (père), université = université (frère), lycée = lycée (celui qui parle).", 'de': "In dem Text heißt es: „Haha, sie arbeitet im Krankenhaus“ (Mutter arbeitet im Krankenhaus). „Kaisha“ = Firma (Vater), „Daigaku“ = Universität (Bruder), „Kōkō“ = Gymnasium (der Sprecher)."})),
      MockQuestion(id: "ja_n5_mock_q017", section: "reading", type: MockQuestionType.multiple_choice, question: "きのうは なんの ひでしたか。", questionEn: "What day was yesterday?", correctAnswer: "たんじょうび", distractors: const ["クリスマス", "にちようび", "やすみのひ"], explanation: const LocalizedText({'en': "The passage begins with きのうは わたしの たんじょうびでした (Yesterday was my birthday). The other options are not mentioned at all.", 'ko': "이 문단은 “어제는 제 생일이었습니다”라는 문장으로 시작합니다. 다른 선택지들은 전혀 언급되지 않았습니다.", 'ja': "文章の最初に「きのうは わたしの たんじょうびでした」と明記されています。", 'zh': "这段文字开头写道：“きのうは わたしの たんじょうびでした”（昨天是我的生日）。其他选项则完全没有提及。", 'zh_TW': "這段文字以「きのうは わたしの たんじょうびでした」（昨天是我的生日）開頭。其他選項則完全未被提及。", 'es': "El texto comienza con «きのうは わたしの たんじょうびでした» (Ayer fue mi cumpleaños). Las demás opciones no se mencionan en absoluto.", 'fr': "Le passage commence par « きのうは わたしの たんじょうびでした » (Hier, c'était mon anniversaire). Les autres options ne sont pas mentionnées du tout.", 'de': "Der Text beginnt mit „きのうは わたしの たんじょうびでした“ (Gestern war mein Geburtstag). Die anderen Optionen werden überhaupt nicht erwähnt."})),
      MockQuestion(id: "ja_n5_mock_q018", section: "reading", type: MockQuestionType.multiple_choice, question: "いえを なんじに でますか。", questionEn: "What time does the person leave home?", correctAnswer: "7じ", distractors: const ["6じ", "8じ", "9じ"], explanation: const LocalizedText({'en': "The passage says 7じに いえを でます (I leave home at 7). 6時 is wake-up time, 8時 is when school starts.", 'ko': "이 문장에는 “7시에 집을 나간다”라고 되어 있습니다. 6시는 기상 시간이고, 8시는 학교가 시작되는 시간입니다.", 'ja': "文中に「7じに いえを でます」と明記されています。", 'zh': "这段文字写道：“7点出门”。6点是起床时间，8点是上学时间。", 'zh_TW': "這段文字提到「7點出門」。6點是起床時間，8點是上學時間。", 'es': "El texto dice: «A las 7 salgo de casa». A las 6 me levanto y a las 8 empieza el colegio.", 'fr': "Le texte dit : « Je pars de chez moi à 7 heures ». Je me réveille à 6 heures et les cours commencent à 8 heures.", 'de': "In dem Text heißt es: „Um 7 Uhr verlasse ich das Haus.“ Um 6 Uhr ist Weckzeit, um 8 Uhr beginnt die Schule."})),
      MockQuestion(id: "ja_n5_mock_q019", section: "reading", type: MockQuestionType.multiple_choice, question: "こうえんに なにが たくさん ありますか。", questionEn: "What is there a lot of in the park?", correctAnswer: "き", distractors: const ["さくら", "こども", "はな"], explanation: const LocalizedText({'en': "The passage states こうえんには きが たくさん あります (There are many trees in the park). さくら (cherry blossoms) are mentioned but not as 'many', こども (children) play there but aren't described as many, はな (flowers) aren't mentioned.", 'ko': "이 문장에는 “공원에는 나무가 많이 있습니다”라고 되어 있습니다. 벚꽃은 언급되었지만 ‘많이’ 있다고는 하지 않았고, 아이들이 그곳에서 놀지만 ‘많이’ 있다고 묘사되지는 않았으며, 꽃은 언급되지 않았습니다.", 'ja': "文中に「こうえんには きが たくさん あります」と書かれています。", 'zh': "这段文字写道：“公园里有很多树”。文中提到了“樱花”，但并未描述其数量众多；孩子们在那里玩耍，但也没有描述为“很多”；而“花”则未被提及。", 'zh_TW': "這段文字提到「公園裡有很多樹」。雖然提到了「櫻花」，但並未形容其數量「很多」；雖然有「孩子」在公園裡玩耍，但並未描述其數量「很多」；而「花」則完全未被提及。", 'es': "El texto dice: «En el parque hay muchos árboles». Se mencionan los cerezos en flor, pero no se dice que haya «muchos»; los niños juegan allí, pero no se dice que haya muchos; y no se mencionan las flores.", 'fr': "Le passage indique : « Il y a beaucoup d'arbres dans le parc ». Les cerisiers en fleurs sont mentionnés, mais pas comme étant « nombreux » ; les enfants y jouent, mais ne sont pas décrits comme étant nombreux ; les fleurs ne sont pas mentionnées.", 'de': "In dem Text heißt es: „Im Park gibt es viele Bäume.“ Kirschblüten werden erwähnt, aber nicht als „viele“; Kinder spielen dort, werden aber nicht als „viele“ beschrieben; Blumen werden nicht erwähnt."})),
      MockQuestion(id: "ja_n5_mock_q020", section: "reading", type: MockQuestionType.multiple_choice, question: "なぜ ともだちに かさを かりましたか。", questionEn: "Why did the person borrow an umbrella from a friend?", correctAnswer: "かさを もって いかなかったから", distractors: const ["かさが こわれたから", "ともだちが かさを ほしがったから", "かぜが つよかったから"], explanation: const LocalizedText({'en': "The passage says わたしは かさを もって いきませんでした。それで...ともだちに かさを かりました (I didn't bring an umbrella. So... I borrowed one from a friend). The cause-effect is clearly stated with それで.", 'ko': "이 문장은 “나는 우산을 가져가지 않았습니다. 그래서... 친구에게 우산을 빌렸습니다”라고 되어 있습니다. ‘그래서’라는 표현을 통해 인과 관계가 명확하게 드러납니다.", 'ja': "文中の「かさを もって いきませんでした。それで...かさを かりました」という因果関係が明確です。", 'zh': "这段话写道：“我没带伞。所以……我向朋友借了一把伞。”通过“所以”一词，因果关系得到了明确的说明。", 'zh_TW': "這段文字寫道：「我沒有帶傘。所以……我向朋友借了一把傘」。透過「所以」一詞，清楚地表達了因果關係。", 'es': "El texto dice: «No me traje el paraguas. Así que... se lo pedí prestado a un amigo». La relación de causa y efecto queda claramente expresada con «así que».", 'fr': "Le passage dit : « Je n'avais pas pris de parapluie. Alors... j'en ai emprunté un à un ami ». Le lien de cause à effet est clairement indiqué par « alors ».", 'de': "In dem Text heißt es: „Ich hatte keinen Regenschirm dabei. Also … habe ich mir einen von einem Freund ausgeliehen.“ Der Zusammenhang zwischen Ursache und Wirkung wird durch „also“ deutlich zum Ausdruck gebracht."})),
      MockQuestion(id: "ja_n5_mock_q021", section: "listening", type: MockQuestionType.multiple_choice, question: "すずきさんは いま どこに いますか。", questionEn: "Where is Suzuki now?", correctAnswer: "えきのまえ", distractors: const ["いえ", "かいしゃ", "こうえん"], explanation: const LocalizedText({'en': "Suzuki says いま えきの まえです (I'm in front of the station now). The other locations are not mentioned.", 'ko': "스즈키는 “지금 역 앞에 있어요”라고 말합니다. 다른 장소에 대해서는 언급되지 않았습니다.", 'ja': "すずきさんが「いま えきの まえです」と言っています。", 'zh': "铃木说：“我现在在车站前面。”其他地点没有提及。", 'zh_TW': "鈴木說：「現在我在車站前面。」其他地點則未提及。", 'es': "Suzuki dice: «Ahora estoy delante de la estación». No se mencionan los demás lugares.", 'fr': "Suzuki dit : « いま えきの まえです » (Je suis devant la gare en ce moment). Les autres lieux ne sont pas mentionnés.", 'de': "Suzuki sagt: „いま えきの まえです“ (Ich bin gerade vor dem Bahnhof). Die anderen Orte werden nicht erwähnt."})),
      MockQuestion(id: "ja_n5_mock_q022", section: "listening", type: MockQuestionType.multiple_choice, question: "りんごを いくつ かいましたか。", questionEn: "How many apples did she buy?", correctAnswer: "3つ", distractors: const ["1つ", "2つ", "4つ"], explanation: const LocalizedText({'en': "The woman says 3つ ください (Please give me 3). One apple costs 100 yen, but the question asks how many she bought, not the price.", 'ko': "그 여자는 “3つ ください(3개 주세요)”라고 말합니다. 사과 한 개는 100엔이지만, 이 문제는 가격이 아니라 그녀가 몇 개를 샀는지를 묻는 것입니다.", 'ja': "女性が「3つ ください」と言っています。1つ100円は値段で、購入数は3つです。", 'zh': "这位女士说“3つ ください”（请给我3个）。一个苹果100日元，但题目问的是她买了多少个，而不是价格。", 'zh_TW': "那位女士說：「3つ ください」（請給我3個）。一個蘋果要100日圓，但題目問的是她買了幾個，而不是價格。", 'es': "La mujer dice «3つ ください» (Por favor, deme tres). Una manzana cuesta 100 yenes, pero la pregunta se refiere a cuántas compró, no al precio.", 'fr': "La femme dit « 3つ ください » (Donnez-m'en trois, s'il vous plaît). Une pomme coûte 100 yens, mais la question porte sur le nombre qu'elle a acheté, pas sur le prix.", 'de': "Die Frau sagt: „3つ ください“ (Bitte geben Sie mir drei). Ein Apfel kostet 100 Yen, aber in der Frage geht es darum, wie viele sie gekauft hat, nicht um den Preis."})),
      MockQuestion(id: "ja_n5_mock_q023", section: "listening", type: MockQuestionType.multiple_choice, question: "いつ えいがを みますか。", questionEn: "When will they watch the movie?", correctAnswer: "らいしゅう", distractors: const ["きょう", "あした", "みません"], explanation: const LocalizedText({'en': "B refuses あした (tomorrow) but accepts らいしゅう (next week), saying らいしゅうは だいじょうぶです. So they will watch next week.", 'ko': "B는 ‘내일’은 거절하지만 ‘다음 주’는 받아들여 “다음 주는 괜찮습니다”라고 말합니다. 그래서 그들은 다음 주에 볼 예정입니다.", 'ja': "Bさんは「あしたは ちょっと...」と断り、「らいしゅうは だいじょうぶです」と了承しています。", 'zh': "B 拒绝了“明天”，但接受了“下周”，并说“下周没问题”。所以他们下周会看。", 'zh_TW': "B 拒絕了「明天」，但接受了「下週」，並說：「下週沒問題。」所以他們將在下週觀看。", 'es': "B rechaza «mañana», pero acepta «la semana que viene», diciendo: «La semana que viene no hay problema». Así que lo verán la semana que viene.", 'fr': "B refuse de venir demain, mais accepte de venir la semaine prochaine, en disant : « La semaine prochaine, ça me va. » Ils se verront donc la semaine prochaine.", 'de': "B lehnt „morgen“ ab, sagt aber „nächste Woche“ zu und erklärt: „Nächste Woche geht es.“ Also werden sie sich die Sendung nächste Woche ansehen."})),
      MockQuestion(id: "ja_n5_mock_q024", section: "listening", type: MockQuestionType.multiple_choice, question: "しゅくだいは なんページまでですか。", questionEn: "Up to what page is the homework?", correctAnswer: "15ページまで", distractors: const ["10ページまで", "5ページまで", "20ページまで"], explanation: const LocalizedText({'en': "The teacher says 10ページから 15ページまで (from page 10 to page 15). So the homework extends up to page 15.", 'ko': "선생님께서 “10페이지부터 15페이지까지”라고 말씀하셨습니다. 그러니 숙제는 15페이지까지입니다.", 'ja': "先生が「10ページから 15ページまで」と言っています。「まで」は終点を表します。", 'zh': "老师说“从第10页到第15页”。所以作业做到第15页为止。", 'zh_TW': "老師說「第10頁到第15頁」。所以作業範圍到第15頁為止。", 'es': "El profesor dice «de la página 10 a la página 15». Así que los deberes llegan hasta la página 15.", 'fr': "Le professeur dit « de la page 10 à la page 15 ». Les devoirs vont donc jusqu'à la page 15.", 'de': "Der Lehrer sagt: „Von Seite 10 bis Seite 15“. Die Hausaufgaben reichen also bis Seite 15."})),
      MockQuestion(id: "ja_n5_mock_q025", section: "listening", type: MockQuestionType.multiple_choice, question: "きのう なにを かいましたか。", questionEn: "What did the person buy yesterday?", correctAnswer: "くつ", distractors: const ["かばん", "ぼうし", "ふく"], explanation: const LocalizedText({'en': "B says くつを かいました (I bought shoes). The follow-up clarifies they are white shoes. The other items are not mentioned.", 'ko': "B는 “신발을 샀어요”라고 말합니다. 이어서 흰색 신발이라는 점이 밝혀집니다. 다른 물건들에 대해서는 언급되지 않았습니다.", 'ja': "Bさんが「くつを かいました」と言っています。白いくつを買ったことも補足されています。", 'zh': "B说“我买了鞋子”。后续内容说明那是白鞋。其他物品则未提及。", 'zh_TW': "B 說：「我買了鞋子」。後續說明指出那是白鞋。其他物品則未提及。", 'es': "B dice: «くつを かいました» (Me compré unos zapatos). A continuación se aclara que son zapatos blancos. No se mencionan los demás artículos.", 'fr': "B dit : « くつを かいました » (J'ai acheté des chaussures). La suite précise qu'il s'agit de chaussures blanches. Les autres articles ne sont pas mentionnés.", 'de': "B sagt: „くつを かいました“ (Ich habe Schuhe gekauft). Im weiteren Verlauf wird klargestellt, dass es sich um weiße Schuhe handelt. Die anderen Gegenstände werden nicht erwähnt."})),
    ],
  );
  static final MockTest jlptN4 = MockTest(
    examName: "JLPT N4",
    language: "ja",
    sections: const [
      MockSection(sectionId: "vocab_mc", title: "語彙 — 多肢選択 (Vocabulary — Multiple Choice)", count: 10),
      MockSection(sectionId: "grammar_fib", title: "文法 — 穴埋め (Grammar — Fill in the Blank)", count: 5),
      MockSection(sectionId: "reading", title: "読解 (Reading Comprehension)", count: 5),
      MockSection(sectionId: "listening", title: "聴解 (Listening — text-based)", count: 5),
    ],
    questions: const [
      MockQuestion(id: "ja_n4_mock_q001", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「しけんが ちかいので、まじめに ＿＿＿。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'Since the exam is near, I will ___ seriously.'?", correctAnswer: "べんきょうする", distractors: const ["けんがくする", "けんぶつする", "りょこうする"], explanation: const LocalizedText({'en': "勉強する (べんきょうする) means 'to study'. The context is exam preparation. 見学する = to tour/visit for study, 見物する = to sightsee, 旅行する = to travel. Only 勉強する makes sense with 試験 (exam).", 'ko': "'勉強する(벤쿄스루)'는 '공부하다'라는 뜻입니다. 문맥상 시험 준비를 의미합니다. '見学する'는 견학하다, '見物する'는 구경하다, '旅行する'는 여행하다라는 뜻입니다. '試験(시험)'과 함께 쓰일 때는 오직 '勉強する'만이 의미가 통합니다.", 'ja': "「勉強する」は「study」の意味です。試験が近いので勉強するという文脈が自然です。", 'zh': "“勉強する”意为“学习”。此处的语境是备考。 “見学する”指为学习目的进行参观， “見物する”指观光， “旅行する”指旅行。只有“勉強する”与“試験”（考试）搭配使用才合理。", 'zh_TW': "「勉強する」意為「學習」。此處的語境是備考。見学する = 為學習而參觀、見物する = 觀光、旅行する = 旅遊。唯有「勉強する」與「考試」搭配使用才合乎語境。", 'es': "«Benkyō suru» significa «estudiar». El contexto es la preparación de un examen. «Kenkyō suru» = hacer una visita de estudio; «miwaku suru» = hacer turismo; «ryokō suru» = viajar. Solo «benkyō suru» tiene sentido en relación con «shiken» (examen).", 'fr': "« 勉強する » (benkyōsuru) signifie « étudier ». Le contexte est celui de la préparation aux examens. « 見学する » = faire une visite guidée/visiter à des fins d'étude, « 見物する » = faire du tourisme, « 旅行する » = voyager. Seul « 勉強する » a du sens avec « 試験 » (examen).", 'de': "„勉強する“ (benkyōsuru) bedeutet „lernen“. Der Kontext ist die Prüfungsvorbereitung. „見学する“ = eine Besichtigungstour machen, „見物する“ = Sehenswürdigkeiten besichtigen, „旅行する“ = reisen. Nur „勉強する“ passt im Zusammenhang mit „試験“ (Prüfung)."})),
      MockQuestion(id: "ja_n4_mock_q002", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「かいぎで 自分の ＿＿＿を しっかり のべた。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'I clearly stated my ___ at the meeting.'?", correctAnswer: "いけん", distractors: const ["しゅみ", "にもつ", "きせつ"], explanation: const LocalizedText({'en': "意見 (いけん) means 'opinion'. 意見を述べる (のべる) = to state one's opinion — a common collocation. 趣味 = hobby, 荷物 = luggage, 季節 = season. None fit the context of a meeting.", 'ko': "'意見(이켄)'은 '의견'을 의미합니다. '意見を述べる(노베루)' = 자신의 의견을 밝히다 — 흔히 쓰이는 표현입니다. '趣味' = 취미, '荷物' = 짐, '季節' = 계절. 이 중 어느 것도 회의 상황에는 맞지 않습니다.", 'ja': "「意見」は「opinion」です。「意見を述べる」は会議での自然な表現です。", 'zh': "“意见”（いけん）意为“意见”。“发表意见”（のべる）= 表达自己的观点——这是一个常见的搭配。趣味 = 爱好，行李 = 行李，季节 = 季节。这些词都不符合会议的语境。", 'zh_TW': "「意見 (いけん)」意為「意見」。「意見を述べる (のべる)」＝表達意見——這是常見的搭配。「趣味」＝興趣、「荷物」＝行李、「季節」＝季節。這些詞彙都不符合會議的語境。", 'es': "Opinión (iken) significa «opinión». Expresar una opinión (noberu) = dar a conocer la propia opinión; una combinación muy habitual. Afición = hobby, equipaje = equipaje, estación = estación del año. Ninguna de estas palabras encaja en el contexto de una reunión.", 'fr': "Le mot « 意見 » (iken) signifie « opinion ». « 意見を述べる » (noberu) = « donner son avis » — une expression courante. « 趣味 » = passe-temps, « 荷物 » = bagages, « 季節 » = saison. Aucun de ces termes ne correspond au contexte d'une réunion.", 'de': "„意見“ (iken) bedeutet „Meinung“. „意見を述べる“ (noberu) = seine Meinung äußern – eine gängige Wortverbindung. „趣味“ = Hobby, „荷物“ = Gepäck, „季節“ = Jahreszeit. Keines dieser Wörter passt in den Kontext einer Besprechung."})),
      MockQuestion(id: "ja_n4_mock_q003", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「この くすりは にがいですが、よく ＿＿＿。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'This medicine is bitter but it ___ well.'?", correctAnswer: "きく", distractors: const ["おこる", "こわれる", "なくなる"], explanation: const LocalizedText({'en': "効く (きく) means 'to be effective'. 薬が効く = the medicine works/is effective. 怒る = to get angry, 壊れる = to break, 無くなる = to disappear/be lost. Only 効く fits with 薬.", 'ko': "'効く(키쿠)'는 '효과가 있다'는 뜻입니다. 薬が効く = 약이 효과가 있다. 怒る = 화를 내다, 壊れる = 부서지다, 無くなる = 사라지다/없어지다. 이 중 '効く'만이 '薬'과 어울립니다.", 'ja': "「効く」は「be effective」の意味です。「薬が効く」は薬の効果を表す自然な表現です。", 'zh': "“効く (kiku)”意为“起作用”。“薬が効く”即“药起作用”。“怒る”意为“生气”，“壊れる”意为“坏掉”，“無くなる”意为“消失/丢失”。只有“効く”与“薬”搭配。", 'zh_TW': "「効く (kiku)」意為「有效」。藥が効く = 藥有效。怒る = 生氣，壊れる = 壞掉，無くなる = 消失／遺失。只有「効く」能與「薬」搭配使用。", 'es': "「効く (kiku)» significa «ser eficaz». 薬が効く = el medicamento funciona/es eficaz. 怒る = enfadarse, 壊れる = romperse, 無くなる = desaparecer/perderse. Solo «効く» encaja con «薬».", 'fr': "« 効く » (kiku) signifie « être efficace ». « 薬が効く » = le médicament agit/est efficace. « 怒る » = se mettre en colère, « 壊れる » = se casser, « 無くなる » = disparaître/se perdre. Seul « 効く » s'accorde avec « 薬 ».", 'de': "„効く“ (kiku) bedeutet „wirken“. „薬が効く“ = das Medikament wirkt. „怒る“ = wütend werden, „壊れる“ = kaputtgehen, „無くなる“ = verschwinden/verloren gehen. Nur „効く“ passt zu „薬“."})),
      MockQuestion(id: "ja_n4_mock_q004", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「この へやの 電気が ＿＿＿から、あかるいです。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'This room's light is ___ so it is bright.'?", correctAnswer: "ついて", distractors: const ["きえて", "おれて", "わかれて"], explanation: const LocalizedText({'en': "つく means 'to turn on / be on' (for lights, fire, electricity). 電気がつく = the light is on. 消える (きえる) = to go out/turn off, 折れる (おれる) = to break/snap, 別れる (わかれる) = to part/separate. Only つく fits the context of a bright room.", 'ko': "‘つく’는 ‘켜다/켜져 있다’는 뜻입니다(불, 조명, 전기의 경우). 電気がつく = 불이 켜져 있다. 消える(키에루) = 꺼지다, 折れる(오레루) = 부러지다, 別れる(와카레루) = 헤어지다. 밝은 방이라는 맥락에 맞는 것은 ‘つく’뿐입니다.", 'ja': "「つく」は電気などが「on」の状態になることです。部屋が明るいのは電気がついているからです。", 'zh': "“つく”意为“打开/亮起”（指灯光、火、电等）。“電気がつく”= 灯亮了。“消える（きえる）”= 熄灭/关掉，“折れる（おれる）”= 折断/断裂，“別れる（わかれる）”= 分离/分开。只有“つく”符合明亮房间的语境。", 'zh_TW': "「つく」意為「打開／亮起」（指燈光、火、電力）。電気がつく = 燈亮了。消える (きえる) = 熄滅／關閉，折れる (おれる) = 折斷／斷裂，別れる (わかれる) = 分離／分開。只有「つく」符合明亮房間的語境。", 'es': "«Tsuku» significa «encenderse / estar encendido» (en referencia a luces, fuego, electricidad). 電気がつく = la luz está encendida. 消える (kieru) = apagarse, 折れる (oreru) = romperse, 別れる (wakareru) = separarse. Solo «tsuku» encaja en el contexto de una habitación iluminada.", 'fr': "« つく » signifie « allumer / être allumé » (pour les lumières, le feu, l'électricité). 電気がつく = la lumière est allumée. 消える (きえる) = s'éteindre / s'éteindre, 折れる (おれる) = se casser / se briser, 別れる (わかれる) = se séparer / se séparer. Seul « つく » correspond au contexte d'une pièce éclairée.", 'de': "„つく“ bedeutet „sich einschalten / an sein“ (für Licht, Feuer, Strom). 電気がつく = das Licht ist an. 消える (きえる) = erlöschen/sich ausschalten, 折れる (おれる) = brechen/knacken, 別れる (わかれる) = sich trennen/sich scheiden. Nur „つく“ passt zum Kontext eines hellen Raums."})),
      MockQuestion(id: "ja_n4_mock_q005", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「まいあさ しんぶんを 読んで、＿＿＿を あつめている。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'Every morning I read the newspaper and gather ___.'?", correctAnswer: "じょうほう", distractors: const ["せいせき", "ゆうびん", "こうつう"], explanation: const LocalizedText({'en': "情報 (じょうほう) means 'information'. Reading newspapers to gather information is a natural activity. 成績 = grades/results, 郵便 = mail/postal, 交通 = traffic/transportation. Only 情報 fits.", 'ko': "‘情報(じょうほう)’는 ‘정보’를 의미합니다. 정보를 얻기 위해 신문을 읽는 것은 자연스러운 행동입니다. 成績 = 성적, 郵便 = 우편, 交通 = 교통. 오직 ‘情報’만이 해당됩니다.", 'ja': "「情報」は「information」です。新聞を読んで情報を集めるのは自然な文脈です。", 'zh': "“情報（じょうほう）”意为“信息”。阅读报纸以获取信息是一种自然而然的行为。成绩 = 成绩/结果，邮政 = 邮件/邮政，交通 = 交通/运输。只有“情報”符合语境。", 'zh_TW': "「情報 (じょうほう)」意為「資訊」。閱讀報紙以獲取資訊是一項自然而然的活動。成績 = 成績／結果，郵便 = 郵件／郵政，交通 = 交通／運輸。只有「情報」符合此語境。", 'es': "«情報» (jōhō) significa «información». Leer periódicos para recabar información es algo natural. 成績 = notas/resultados, 郵便 = correo/servicio postal, 交通 = tráfico/transporte. Solo encaja «情報».", 'fr': "情報 (jōhō) signifie « information ». Lire les journaux pour s'informer est une activité tout à fait naturelle. 成績 = notes/résultats, 郵便 = courrier/poste, 交通 = circulation/transports. Seul le mot 情報 convient.", 'de': "情報 (じょうほう) bedeutet „Informationen“. Zeitungen zu lesen, um Informationen zu sammeln, ist eine ganz natürliche Tätigkeit. 成績 = Noten/Ergebnisse, 郵便 = Post, 交通 = Verkehr/Transport. Nur 情報 passt hierher."})),
      MockQuestion(id: "ja_n4_mock_q006", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「かのじょは せが たかくて、＿＿＿が いいです。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'She is tall and has a good ___.'?", correctAnswer: "スタイル", distractors: const ["あたま", "かお", "くび"], explanation: const LocalizedText({'en': "スタイル means 'figure/style'. スタイルがいい = has a good figure. Describing someone's physique with 背が高い (tall) and スタイルがいい (good figure) is a natural pairing. 頭 = head, 顔 = face, 首 = neck — none naturally pair with 背が高い.", 'ko': "'스타일'은 '체형/스타일'을 의미합니다. '스타일이 좋다'는 '체형이 좋다'는 뜻입니다. 누군가의 체격을 설명할 때 '키가 크다'와 '스타일이 좋다'는 표현은 자연스럽게 어울리는 조합입니다. '머리', '얼굴', '목'은 '키가 크다'와 자연스럽게 어울리지 않습니다.", 'ja': "「スタイル」は体つきや姿のことです。「スタイルがいい」は「背が高い」と並んで外見を表す自然な表現です。", 'zh': "“スタイル”意为“身材/风格”。“スタイルがいい”即“身材好”。用“背が高い”（个子高）和“スタイルがいい”（身材好）来形容某人的体态，是十分自然的搭配。而“頭”（头）、“顔”（脸）、“首”（脖子）——这些词与“背が高い”则没有自然的搭配关系。", 'zh_TW': "「スタイル」意為「身材／風格」。「スタイルがいい」即指「身材好」。用「背が高い」（高）和「スタイルがいい」（身材好）來形容某人的體態，是相當自然的搭配。而「頭」、「顔」、「首」——這些詞語則自然不會與「背が高い」搭配使用。", 'es': "«スタイル» significa «figura/estilo». «スタイルがいい» = tiene buena figura. Describir el físico de alguien con «背が高い» (alto) y «スタイルがいい» (buena figura) es una combinación natural. «頭» = cabeza, «顔» = cara, «首» = cuello: ninguno de ellos se combina de forma natural con «背が高い».", 'fr': "スタイル signifie « silhouette ». スタイルがいい = avoir une belle silhouette. Décrire le physique d'une personne en utilisant 背が高い (grand) et スタイルがいい (belle silhouette) est une association naturelle. 頭 = tête, 顔 = visage, 首 = cou — aucun de ces termes ne s'associe naturellement à 背が高い.", 'de': "„スタイル“ bedeutet „Figur/Stil“. „スタイルがいい“ = hat eine gute Figur. Die Beschreibung der Statur einer Person mit „背が高い“ (groß) und „スタイルがいい“ (gute Figur) ist eine natürliche Kombination. „頭“ = Kopf, „顔“ = Gesicht, „首“ = Hals – keines dieser Wörter passt von Natur aus zu „背が高い“."})),
      MockQuestion(id: "ja_n4_mock_q007", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「にもつが おもいので、だれかに ＿＿＿ もらいました。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'The luggage was heavy, so I had someone ___ it for me.'?", correctAnswer: "もって", distractors: const ["すてて", "なくして", "おとして"], explanation: const LocalizedText({'en': "持つ (もつ) means 'to carry/hold'. 持ってもらう = to have someone carry (for you). 捨てる = throw away, 無くす = lose, 落とす = drop. In the context of heavy luggage, having someone carry it makes sense.", 'ko': "「持つ(모츠)」는 ‘들다/가지고 있다’는 뜻입니다. 「持ってもらう」은 ‘누군가에게 (자신을 위해) 들어달라고 부탁하다’는 의미입니다. 「捨てる」는 ‘버리다’, 「無くす」는 ‘잃어버리다’, 「落とす」는 ‘떨어뜨리다’입니다. 무거운 짐을 다룰 때, 누군가에게 들어달라고 부탁하는 것은 자연스러운 일입니다.", 'ja': "「持つ」は「carry」の意味です。「〜てもらう」と組み合わせて「持ってもらう」=「運んでもらう」の意味になります。", 'zh': "“持つ (もつ)”意为“携带/拿着”。“持ってもらう”即“请别人帮忙拿”。“捨てる”是“扔掉”，“無くす”是“弄丢”，“落とす”是“掉落”。在谈论沉重行李的语境下，请别人帮忙拿是合情合理的。", 'zh_TW': "「持つ (もつ)」意為「攜帶／拿著」。持ってもらう = 請別人幫忙攜帶。捨てる = 丟棄，無くす = 弄丟，落とす = 掉落。在談論沉重行李的語境下，請別人幫忙攜帶是合情合理的。", 'es': "「持つ (もつ)」significa «llevar/sostener». 「持ってもらう」 = que alguien lo lleve (por ti). 「捨てる」 = tirar, 「無くす」 = perder, 「落とす」 = dejar caer. En el contexto del equipaje pesado, tiene sentido que alguien lo lleve.", 'fr': "「持つ (もつ) » signifie « porter ». « 持ってもらう » = se faire porter (par quelqu'un). « 捨てる » = jeter, « 無くす » = perdre, « 落とす » = faire tomber. Dans le cas de bagages lourds, il est logique de se faire porter par quelqu'un.", 'de': "„持つ (motsu)“ bedeutet „tragen/halten“. „持ってもらう“ = jemanden bitten, etwas (für einen) zu tragen. „捨てる“ = wegwerfen, „無くす“ = verlieren, „落とす“ = fallen lassen. Im Zusammenhang mit schwerem Gepäck ist es sinnvoll, jemanden bitten, es zu tragen."})),
      MockQuestion(id: "ja_n4_mock_q008", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「あのレストランは いつも ＿＿＿で こんでいる。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'That restaurant is always crowded with ___.'?", correctAnswer: "きゃく", distractors: const ["しなもの", "てんいん", "しゃちょう"], explanation: const LocalizedText({'en': "客 (きゃく) means 'customers/guests'. 客で込んでいる = crowded with customers — natural for a restaurant. 品物 = goods/products, 店員 = store clerk, 社長 = company president. Only 客 makes sense for restaurant crowds.", 'ko': "'客(きゃく)'는 '손님'을 의미합니다. '客で込んでいる'은 '손님으로 붐비다'라는 뜻으로, 식당에서는 흔히 볼 수 있는 표현입니다. '品物'은 '상품', '店員'은 '점원', '社長'은 '사장'을 뜻합니다. 식당의 붐비는 상황을 설명할 때는 오직 '客'만이 적절한 표현입니다.", 'ja': "「客」は「customer」です。レストランが客で混んでいるのは自然な表現です。", 'zh': "“客（きゃく）”意为“顾客/客人”。“客で込んでいる”即“挤满了顾客”——这在餐厅里很常见。“品物”指“商品/产品”，“店員”指“店员”，“社長”指“公司总裁”。只有“客”这个词才能准确描述餐厅里的人群。", 'zh_TW': "「客 (きゃく)」意為「顧客／客人」。「客で込んでいる」即為「顧客眾多」——這在餐廳裡是再自然不過的景象。「品物」指「商品／產品」，「店員」指「店員」，「社長」指「公司社長」。唯有「客」一詞能準確形容餐廳裡的人潮。", 'es': "「客 (kyaku)» significa «clientes/invitados». «客で込んでいる» = lleno de clientes — algo habitual en un restaurante. 「品物」 = mercancías/productos, 「店員」 = dependiente, 「社長」 = director de la empresa. Solo «客» tiene sentido para referirse a la afluencia de gente en un restaurante.", 'fr': "Le mot 客 (kyaku) signifie « clients/invités ». 客で込んでいる = bondé de clients — ce qui est tout à fait normal pour un restaurant. 品物 = marchandises/produits, 店員 = vendeur, 社長 = président de l'entreprise. Seul le mot 客 a du sens pour désigner la foule dans un restaurant.", 'de': "客 (kyaku) bedeutet „Kunden/Gäste“. 客で込んでいる = voller Kunden – was für ein Restaurant ganz normal ist. 品物 = Waren/Produkte, 店員 = Verkäufer, 社長 = Firmenchef. Nur 客 ergibt im Zusammenhang mit einem überfüllten Restaurant Sinn."})),
      MockQuestion(id: "ja_n4_mock_q009", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「しごとに ＿＿＿して、まいにち おそくまで はたらいています。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'I am ___ about my work and work late every day.'?", correctAnswer: "ねっしん", distractors: const ["たいくつ", "ふあん", "ざんねん"], explanation: const LocalizedText({'en': "熱心 (ねっしん) means 'enthusiastic/zealous'. 仕事に熱心だ = to be enthusiastic about work. 退屈 = boredom, 不安 = anxiety, 残念 = regrettable/unfortunate. Only 熱心 fits a context of working late voluntarily.", 'ko': "'熱心(네신)'은 '열정적인, 열성적인'이라는 뜻입니다. '仕事に熱心だ'는 '일에 열정적이다'라는 의미입니다. '退屈'은 '지루함', '不安'은 '불안', '残念'은 '유감스럽다, 안타깝다'를 뜻합니다. 자발적으로 야근을 하는 맥락에는 오직 '熱心'만이 어울립니다.", 'ja': "「熱心」は「enthusiastic」の意味です。仕事に熱心で遅くまで働くのは自然な文脈です。", 'zh': "“热心”意为“热情/热忱”。“工作中很热心”=对工作充满热情。“退屈”=无聊，“不安”=焦虑，“遗憾”=遗憾/不幸。只有“热心”符合自愿加班的语境。", 'zh_TW': "「熱心 (ねっしん)」意為「熱忱／積極」。例如：「仕事に熱心だ」即表示「對工作充滿熱忱」。「退屈」意為「無聊」，「不安」意為「焦慮」，「残念」意為「遺憾／可惜」。在自願加班的語境下，唯有「熱心」一詞最為貼切。", 'es': "熱心 (nesshin) significa «entusiasta/diligente». 仕事に熱心だ = ser entusiasta con el trabajo. 退屈 = aburrimiento, 不安 = ansiedad, 残念 = lamentable/desafortunado. Solo 熱心 encaja en un contexto de trabajar hasta tarde por voluntad propia.", 'fr': "熱心 (nesshin) signifie « enthousiaste / zélé ». 仕事に熱心だ = être enthousiaste au travail. 退屈 = ennui, 不安 = anxiété, 残念 = regrettable / malheureux. Seul 熱心 correspond au contexte du fait de travailler tard de son plein gré.", 'de': "熱心 (nesshin) bedeutet „begeistert/eifrig“. 仕事に熱心だ = sich für die Arbeit begeistern. 退屈 = Langeweile, 不安 = Angst, 残念 = bedauerlich/unglücklich. Nur 熱心 passt in den Kontext, freiwillig länger zu arbeiten."})),
      MockQuestion(id: "ja_n4_mock_q010", section: "vocab_mc", type: MockQuestionType.multiple_choice, question: "「けさ おきたとき、のどが ＿＿＿ いたかった。」にあてはまる ことばは どれですか。", questionEn: "Which word fits: 'When I woke up this morning, my throat hurt ___.'?", correctAnswer: "とても", distractors: const ["わざと", "なかなか", "すっかり"], explanation: const LocalizedText({'en': "とても means 'very'. のどがとても痛い = my throat hurts very much. わざと = intentionally/on purpose, なかなか = quite/considerably (often with negative), すっかり = completely/entirely. とても is the most natural intensifier for pain.", 'ko': "'とても'는 '매우'라는 뜻입니다. 'のどがとても痛い' = 목이 매우 아파요. 'わざと' = 일부러, 'なかなか' = 꽤/상당히 (주로 부정문에서 사용), 'すっかり' = 완전히/전적으로. 'とても'는 통증을 표현할 때 가장 자연스럽게 쓰이는 강조어입니다.", 'ja': "「とても」は「very」の意味で、痛みの程度を表すのに最も自然な副詞です。", 'zh': "“とても”意为“非常”。“のどがとても痛い”=“我的喉咙非常痛”。“わざと”=“故意地/特意地”，“なかなか”=“相当/颇为”（常用于否定句中），“すっかり”=“完全地/彻底地”。“とても”是表达疼痛时最自然的强调词。", 'zh_TW': "「とても」的意思是「非常」。「のどがとても痛い」＝「我的喉嚨非常痛」。「わざと」＝「故意」、「なかなか」＝「頗為／相當」（常與否定語搭配使用）、「すっかり」＝「完全／徹底地」。「とても」是描述疼痛時最自然的強化詞。", 'es': "«とても» significa «mucho». «のどがとても痛い» = me duele mucho la garganta. «わざと» = a propósito, «なかなか» = bastante (a menudo con sentido negativo), «すっかり» = completamente. «とても» es el intensificador más natural para expresar dolor.", 'fr': "« とても » signifie « très ». « のどがとても痛い » = j'ai très mal à la gorge. « わざと » = intentionnellement/exprès, « なかなか » = assez/beaucoup (souvent avec une nuance négative), « すっかり » = complètement/entièrement. « とても » est le intensificateur le plus naturel pour exprimer la douleur.", 'de': "„とても“ bedeutet „sehr“. „のどがとても痛い“ = „Ich habe starke Halsschmerzen“. „わざと“ = „absichtlich/mit Absicht“, „なかなか“ = „ziemlich/erheblich“ (oft in negativen Sätzen), „すっかり“ = „vollständig/ganz“. „とても“ ist die natürlichste Verstärkung für Schmerzen."})),
      MockQuestion(id: "ja_n4_mock_q011", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "天気予報によると、あしたは 雪が ＿＿＿そうです。 (ふる / ふります)", questionEn: "Fill in the blank: 'According to the forecast, I hear it will ___ tomorrow.' (fall/snow)", correctAnswer: "ふる", distractors: const ["ふった", "ふっている", "ふります"], explanation: const LocalizedText({'en': "〜そうです (hearsay) requires the plain/dictionary form before it. ふる is the dictionary form of 降る (to fall/snow).", 'ko': "〜そうです(전문) 앞에는 보통형을 사용합니다. 「ふる」는 「降る」의 사전형입니다.", 'ja': "〜そうです（伝聞）の前には普通形を使います。「ふる」は「降る」の辞書形です。", 'zh': "〜そうです（传闻）前需要用简体形。「ふる」是「降る」的辞书形。", 'zh_TW': "〜そうです（傳聞）前需要用普通形。「ふる」是「降る」的辭書形。", 'es': "〜そうです (rumores) requiere la forma simple antes. ふる es la forma de diccionario de 降る.", 'fr': "〜そうです (ouï-dire) nécessite la forme simple avant. ふる est la forme du dictionnaire de 降る.", 'de': "〜そうです (Hörensagen) erfordert die Grundform davor. ふる ist die Wörterbuchform von 降る."})),
      MockQuestion(id: "ja_n4_mock_q012", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "この しごとを ＿＿＿ もらいました。 (てつだう / てつだいます)", questionEn: "Fill in the blank: 'I had someone ___ me with this work.' (help)", correctAnswer: "てつだって", distractors: const ["てつだい", "てつだう", "てつだいます"], explanation: const LocalizedText({'en': "て-form + もらいました means \"had someone do something for me.\" てつだって is the て-form of 手伝う (to help).", 'ko': "て형＋もらいました는 「〜해 주었다」라는 의미입니다. 「てつだって」는 「手伝う」의 て형입니다.", 'ja': "て形＋もらいましたは「〜してもらった」という意味です。「てつだって」は「手伝う」のて形です。", 'zh': "て形＋もらいました表示\"请别人为自己做了某事\"。「てつだって」是「手伝う」的て形。", 'zh_TW': "て形＋もらいました表示「請別人為自己做了某事」。「てつだって」是「手伝う」的て形。", 'es': "Forma て + もらいました significa \"alguien hizo algo por mí\". てつだって es la forma て de 手伝う.", 'fr': "Forme て + もらいました signifie \"quelqu'un a fait quelque chose pour moi\". てつだって est la forme て de 手伝う.", 'de': "て-Form + もらいました bedeutet \"jemand hat etwas für mich getan\". てつだって ist die て-Form von 手伝う."})),
      MockQuestion(id: "ja_n4_mock_q013", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "日本語が 上手に ＿＿＿ ように、まいにち れんしゅうしています。 (はなす / はなします)", questionEn: "Fill in the blank: 'I practice every day so that I ___ speak Japanese well.' (speak)", correctAnswer: "話せる", distractors: const ["話す", "話した", "話します"], explanation: const LocalizedText({'en': "Potential form + ように means \"so that I can...\" 話せる is the potential form of 話す (to speak).", 'ko': "가능형＋ように는 「〜할 수 있도록」이라는 의미입니다. 「話せる」는 「話す」의 가능형입니다.", 'ja': "可能形＋ように は「〜できるように」という意味です。「話せる」は「話す」の可能形です。", 'zh': "可能形＋ように表示\"为了能够...\"。「話せる」是「話す」的可能形。", 'zh_TW': "可能形＋ように表示「為了能夠...」。「話せる」是「話す」的可能形。", 'es': "Forma potencial + ように significa \"para poder...\". 話せる es la forma potencial de 話す.", 'fr': "Forme potentielle + ように signifie \"pour pouvoir...\". 話せる est la forme potentielle de 話す.", 'de': "Potentialform + ように bedeutet \"damit ich ... kann\". 話せる ist die Potentialform von 話す."})),
      MockQuestion(id: "ja_n4_mock_q014", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "まだ そうじを して いません。今から ＿＿＿ つもりです。 (する / します)", questionEn: "Fill in the blank: 'I haven't cleaned yet. I ___ to do it from now.' (intend to do)", correctAnswer: "する", distractors: const ["した", "している", "します"], explanation: const LocalizedText({'en': "Dictionary form + つもりです means \"I intend to...\" する is the dictionary form of する (to do).", 'ko': "사전형＋つもりです는 「〜할 작정이다」라는 의미입니다. 「する」는 「する」의 사전형입니다.", 'ja': "辞書形＋つもりです は「〜するつもりだ」という意味です。「する」は「する」の辞書形です。", 'zh': "辞书形＋つもりです表示\"打算...\"。「する」是「する」的辞书形。", 'zh_TW': "辭書形＋つもりです表示「打算...」。「する」是「する」的辭書形。", 'es': "Forma de diccionario + つもりです significa \"tengo la intención de...\". する es la forma de diccionario de する.", 'fr': "Forme du dictionnaire + つもりです signifie \"j'ai l'intention de...\". する est la forme du dictionnaire de する.", 'de': "Wörterbuchform + つもりです bedeutet \"ich habe vor zu...\". する ist die Wörterbuchform von する."})),
      MockQuestion(id: "ja_n4_mock_q015", section: "grammar_fib", type: MockQuestionType.fill_in_blank, question: "この かばんは ＿＿＿ やすいです。 (もつ / もちます)", questionEn: "Fill in the blank: 'This bag is easy to ___.' (carry)", correctAnswer: "持ち", distractors: const ["持つ", "持った", "持ちます"], explanation: const LocalizedText({'en': "Verb stem (masu-stem) + やすい means \"easy to...\" 持ち is the masu-stem of 持つ (to carry/hold).", 'ko': "동사의 ます형 어간＋やすい는 「〜하기 쉽다」라는 의미입니다. 「持ち」는 「持つ」의 ます형 어간입니다.", 'ja': "動詞のます形の語幹＋やすい は「〜しやすい」という意味です。「持ち」は「持つ」のます形の語幹です。", 'zh': "动词ます形词干＋やすい表示\"容易...\"。「持ち」是「持つ」的ます形词干。", 'zh_TW': "動詞ます形詞幹＋やすい表示「容易...」。「持ち」是「持つ」的ます形詞幹。", 'es': "Raíz verbal (raíz masu) + やすい significa \"fácil de...\". 持ち es la raíz masu de 持つ.", 'fr': "Radical du verbe (radical masu) + やすい signifie \"facile à...\". 持ち est le radical masu de 持つ.", 'de': "Verbstamm (masu-Stamm) + やすい bedeutet \"leicht zu...\". 持ち ist der masu-Stamm von 持つ."})),
      MockQuestion(id: "ja_n4_mock_q016", section: "reading", type: MockQuestionType.multiple_choice, question: "山の上から なにが よく 見えましたか。", questionEn: "What could be seen well from the top of the mountain?", correctAnswer: "まち", distractors: const ["ともだちの いえ", "でんしゃ", "がっこう"], explanation: const LocalizedText({'en': "The passage says 山の上からは町がよく見えました (From the top of the mountain, the town was clearly visible). 町 = town. No other location was visible from the mountain top.", 'ko': "이 문장은 “산 위에서는 마을이 잘 보였습니다”라고 되어 있습니다. ‘마을’은 마을을 의미합니다. 산 정상에서는 다른 장소는 보이지 않았습니다.", 'ja': "文中に「山の上からは町がよく見えました」と明記されています。", 'zh': "文中写道：“山の上からは町がよく見えました”（从山顶上，小镇清晰可见）。“町”即指小镇。从山顶上无法看到其他地方。", 'zh_TW': "文中提到「從山頂上可以清楚地看到鎮子」。鎮子 = town。從山頂上看不到其他地點。", 'es': "El texto dice: «山の上からは町がよく見えました» (Desde la cima de la montaña se veía claramente el pueblo). 町 = pueblo. Desde la cima de la montaña no se veía ningún otro lugar.", 'fr': "Le passage dit : « 山の上からは町がよく見えました » (Du sommet de la montagne, on voyait bien la ville). 町 = ville. Aucun autre endroit n'était visible depuis le sommet de la montagne.", 'de': "In dem Text heißt es: „山の上からは町がよく見えました“ (Vom Gipfel des Berges aus war die Stadt gut zu sehen). 町 = Stadt. Vom Gipfel des Berges aus war kein anderer Ort zu sehen."})),
      MockQuestion(id: "ja_n4_mock_q017", section: "reading", type: MockQuestionType.multiple_choice, question: "田中さんは どうして 雨の日も 走りますか。", questionEn: "Why does Mr. Tanaka run even on rainy days?", correctAnswer: "走ることが 好きだから", distractors: const ["かいしゃに ちこくしたくないから", "やせたいから", "ともだちと やくそくしたから"], explanation: const LocalizedText({'en': "The passage states 走ることが好きだからだそうです (It's because he likes running). This directly answers the question. The other reasons are not mentioned.", 'ko': "본문에는 “달리는 것을 좋아하기 때문이라고 합니다”라고 나와 있습니다. 이는 질문에 대한 직접적인 답변입니다. 다른 이유들은 언급되지 않았습니다.", 'ja': "文中に「走ることが好きだからだそうです」と理由が明記されています。", 'zh': "文中提到“据说是因为他喜欢跑步”。这直接回答了问题。其他原因则未提及。", 'zh_TW': "該段落提到「走することが好きだからだそうです」（據說是因為他喜歡跑步）。這直接回答了問題。其他原因則未提及。", 'es': "El texto dice: «Se dice que es porque le gusta correr». Esto responde directamente a la pregunta. No se mencionan otras razones.", 'fr': "Le passage indique : « C'est parce qu'il aime courir », semble-t-il. Cela répond directement à la question. Les autres raisons ne sont pas mentionnées.", 'de': "In dem Text heißt es: „走ることが好きだからだそうです“ (Weil er gerne läuft). Das beantwortet die Frage direkt. Die anderen Gründe werden nicht erwähnt."})),
      MockQuestion(id: "ja_n4_mock_q018", section: "reading", type: MockQuestionType.multiple_choice, question: "お目当ての本は いつ 買えますか。", questionEn: "When can the desired book be bought?", correctAnswer: "らいしゅう", distractors: const ["きのう", "きょう", "まだ わからない"], explanation: const LocalizedText({'en': "The passage says 来週入荷するそうです (I hear it will arrive next week). So the book will be available next week. 昨日 = yesterday (when they went), 今日 is not mentioned.", 'ko': "본문에는 “다음 주에 입고될 예정이라고 합니다”라고 되어 있습니다. 따라서 그 책은 다음 주부터 구할 수 있을 것입니다. ‘어제’는 그들이 갔던 날을 의미하며, ‘오늘’에 대해서는 언급되어 있지 않습니다.", 'ja': "店員が「来週入荷するそうです」と伝えたので、来週買えることになります。", 'zh': "文中提到“据说下周到货”（I hear it will arrive next week）。所以这本书下周就能买到了。“昨日”指昨天（他们去的时候），文中未提及“今日”。", 'zh_TW': "這段文字提到「據說下週到貨」，因此這本書下週就會有貨。昨日 = 昨天（他們去的時候），今日則未提及。", 'es': "El texto dice: «来週入荷するそうです» (He oído que llegará la semana que viene). Así que el libro estará disponible la semana que viene. «昨日» = ayer (cuando fueron); «今日» no se menciona.", 'fr': "Le texte indique : « 来週入荷するそうです » (Il paraît qu'il arrivera la semaine prochaine). Le livre sera donc disponible la semaine prochaine. 昨日 = hier (quand ils y sont allés), 今日 n'est pas mentionné.", 'de': "In dem Text heißt es: „来週入荷するそうです“ (Ich habe gehört, dass es nächste Woche eintreffen soll). Das Buch wird also nächste Woche erhältlich sein. „昨日“ = gestern (als sie dort waren), „今日“ wird nicht erwähnt."})),
      MockQuestion(id: "ja_n4_mock_q019", section: "reading", type: MockQuestionType.multiple_choice, question: "空港に着いたとき、どうして こまりましたか。", questionEn: "Why was the person troubled when arriving at the airport?", correctAnswer: "にほんごが つうじなかったから", distractors: const ["にもつを なくしたから", "おかねが たりなかったから", "ホテルが みつからなかったから"], explanation: const LocalizedText({'en': "The passage states 日本語がなかなか通じなくて困りました (I had trouble because my Japanese wasn't understood well). This is a direct statement of the problem.", 'ko': "이 문장은 “일본어가 잘 통하지 않아 곤란했습니다”라고 적혀 있습니다. 이는 문제를 직접적으로 언급한 것입니다.", 'ja': "文中に「日本語がなかなか通じなくて困りました」と明記されています。", 'zh': "该段落写道：“日本語がなかなか通じなくて困りました”（因为我的日语不太被理解，所以很困扰）。这是对该问题的直接陈述。", 'zh_TW': "該段落提到：「日本語がなかなか通じなくて困りました」（因為我的日語不太被理解，所以感到很困擾）。這正是對該問題的直接陳述。", 'es': "El texto dice: «日本語がなかなか通じなくて困りました» (Tuve problemas porque no se entendía bien mi japonés). Se trata de una descripción directa del problema.", 'fr': "Le passage dit : « 日本語がなかなか通じなくて困りました » (J'ai eu du mal parce que mon japonais n'était pas bien compris). Il s'agit là d'une description directe du problème.", 'de': "In dem Text heißt es: „日本語がなかなか通じなくて困りました“ (Ich hatte Probleme, weil mein Japanisch nicht gut verstanden wurde). Dies ist eine direkte Beschreibung des Problems."})),
      MockQuestion(id: "ja_n4_mock_q020", section: "reading", type: MockQuestionType.multiple_choice, question: "どうして アルバイトを 探していますか。", questionEn: "Why is the person looking for a part-time job?", correctAnswer: "りょこうの おかねを ためたいから", distractors: const ["あたらしい くるまを かいたいから", "がっこうの おかねが ひつようだから", "ともだちに すすめられたから"], explanation: const LocalizedText({'en': "The passage says 来年の旅行のためにお金を貯めたいから (because I want to save money for next year's trip). This is the direct reason. The friend's recommendation was for a specific job, not the reason for job hunting.", 'ko': "본문에는 “내년 여행을 위해 돈을 모으고 싶어서”라고 나와 있습니다. 이것이 직접적인 이유입니다. 친구가 추천한 것은 특정 직종이었지, 구직 활동의 이유가 아니었습니다.", 'ja': "文中に「来年の旅行のためにお金を貯めたいから」と理由が明記されています。", 'zh': "文中提到“因为我想为明年的旅行存钱”。这是直接原因。朋友的推荐针对的是具体的工作，而不是求职的原因。", 'zh_TW': "文中提到「因為我想為明年的旅行存錢」，這是直接原因。朋友的推薦是針對某份特定工作，而非求職的理由。", 'es': "El texto dice: «来年の旅行のためにお金を貯めたいから» (porque quiero ahorrar dinero para el viaje del año que viene). Esa es la razón directa. La recomendación del amigo se refería a un trabajo concreto, no era el motivo por el que estaba buscando empleo.", 'fr': "Le passage dit : « 来年の旅行のためにお金を貯めたいから » (parce que je veux économiser de l'argent pour le voyage de l'année prochaine). C'est là la raison directe. La recommandation de l'ami concernait un emploi précis, et non la raison pour laquelle il cherchait un emploi.", 'de': "In dem Text heißt es: „来年の旅行のためにお金を貯めたいから“ (weil ich Geld für die Reise im nächsten Jahr sparen möchte). Das ist der unmittelbare Grund. Die Empfehlung des Freundes bezog sich auf eine bestimmte Stelle, nicht auf den Grund für die Jobsuche."})),
      MockQuestion(id: "ja_n4_mock_q021", section: "listening", type: MockQuestionType.multiple_choice, question: "市役所に行くには、何番目の信号を曲がりますか。", questionEn: "At which traffic light should you turn to go to the city hall?", correctAnswer: "二つ目", distractors: const ["一つ目", "三つ目", "曲がらなくていい"], explanation: const LocalizedText({'en': "B says 二つ目の信号を右に曲がってください (turn right at the second traffic light). A confirms this, and B agrees. 一つ目 = first, 三つ目 = third.", 'ko': "B가 “두 번째 신호등에서 우회전해 주세요”라고 말합니다. A가 이를 확인하고, B도 동의합니다. 첫 번째 = first, 세 번째 = third.", 'ja': "Bさんが「二つ目の信号を右に曲がってください」と言っています。", 'zh': "B说：“请在第二个红绿灯处右转。”A表示明白，B表示同意。“第一个”指第一个，“第三个”指第三个。", 'zh_TW': "B 說：「請在第二個紅綠燈處右轉。」A 確認了這點，B 也表示同意。第一個 = first，第三個 = third。", 'es': "B dice: «Gire a la derecha en el segundo semáforo». A lo confirma y B está de acuerdo. El primero = first, el tercero = third.", 'fr': "B dit : « Tournez à droite au deuxième feu » (turn right at the second traffic light). A confirme, et B acquiesce. Le premier = first, le troisième = third.", 'de': "B sagt: „Bitte biegen Sie an der zweiten Ampel rechts ab.“ A bestätigt dies, und B stimmt zu. Erste = first, dritte = third."})),
      MockQuestion(id: "ja_n4_mock_q022", section: "listening", type: MockQuestionType.multiple_choice, question: "Bさんは どうして けっこんしきに 出られませんか。", questionEn: "Why can't B attend the wedding?", correctAnswer: "ようじが あるから", distractors: const ["びょうきだから", "たびに いくから", "おかねが ないから"], explanation: const LocalizedText({'en': "B says その日はちょっと用事があって行けない (I have something to do that day so I can't go). 用事 = errand/business/prior engagement. The other reasons are not mentioned.", 'ko': "B는 “그날은 할 일이 있어서 갈 수 없다”고 말합니다. ‘용사’는 심부름, 업무, 또는 미리 잡힌 약속을 의미합니다. 그 외의 이유는 언급되지 않았습니다.", 'ja': "Bさんが「その日はちょっと用事があって行けない」と言っています。", 'zh': "B说：“那天我有点事，去不了。”（I have something to do that day so I can't go）。“用事”指杂事、公务或已有安排。其他原因未提及。", 'zh_TW': "B 說：「那天我有事，去不了。」「有事」指代雜務、公務或既有約定。其他原因則未提及。", 'es': "B dice: «Ese día tengo algo que hacer, así que no puedo ir». «用事» significa «recado», «asunto» o «compromiso previo». No se mencionan otras razones.", 'fr': "B dit : « J'ai quelque chose à faire ce jour-là, donc je ne peux pas venir. » (用事 = course / affaire / engagement préalable). Les autres raisons ne sont pas mentionnées.", 'de': "B sagt: „An diesem Tag habe ich etwas zu erledigen, deshalb kann ich nicht kommen.“ „用事“ bedeutet „Besorgung“, „Geschäft“ oder „vorherige Verpflichtung“. Die anderen Gründe werden nicht erwähnt."})),
      MockQuestion(id: "ja_n4_mock_q023", section: "listening", type: MockQuestionType.multiple_choice, question: "忘れた傘は どんな かさですか。", questionEn: "What kind of umbrella was left behind?", correctAnswer: "あおくて ながい", distractors: const ["あかくて みじかい", "しろくて おれている", "くろくて ふとい"], explanation: const LocalizedText({'en': "A describes the umbrella as 青くて、長い傘です (blue and long). The other color/shape combinations don't match the description.", 'ko': "A는 그 우산을 “파란색이고 긴 우산”이라고 묘사합니다. 다른 색상이나 모양의 조합은 이 묘사와 일치하지 않습니다.", 'ja': "Aさんが「青くて、長い傘です」と説明しています。", 'zh': "A 描述这把伞是“青色且修长的伞”。其他颜色和形状的组合都不符合这一描述。", 'zh_TW': "A 將這把傘描述為「青色且長」的傘。其餘的顏色與形狀組合都不符合這項描述。", 'es': "A describe el paraguas como «un paraguas azul y largo». Las demás combinaciones de colores y formas no se ajustan a la descripción.", 'fr': "A décrit le parapluie comme étant « bleu et long ». Les autres combinaisons de couleurs et de formes ne correspondent pas à cette description.", 'de': "A beschreibt den Regenschirm als „blau und lang“. Die anderen Farb- und Formkombinationen entsprechen nicht dieser Beschreibung."})),
      MockQuestion(id: "ja_n4_mock_q024", section: "listening", type: MockQuestionType.multiple_choice, question: "いつ えいがを 見に 行きますか。", questionEn: "When will they go see the movie?", correctAnswer: "日曜日の 午後2時", distractors: const ["土曜日の 午後2時", "土曜日の 午前中", "日曜日の 午前中"], explanation: const LocalizedText({'en': "A proposes 日曜の午後2時からの回 (the 2 PM showing on Sunday), and B agrees enthusiastically. 土曜日 = Saturday, 午前中 = in the morning — not mentioned.", 'ko': "A는 일요일 오후 2시 상영을 제안하고, B는 열정적으로 동의한다. 토요일 = Saturday, 오전 = in the morning — 언급되지 않음.", 'ja': "Aさんが「日曜の午後2時からの回にしようか」と提案し、Bさんが同意しています。", 'zh': "A提议看周日下午2点的场次，B欣然同意。周六 = Saturday，上午 = in the morning —— 未提及。", 'zh_TW': "A 提議觀看「週日下午2點的場次」，B 欣然同意。週六 = Saturday，上午 = in the morning — 未提及。", 'es': "A propone la sesión de las 2 de la tarde del domingo, y B acepta con entusiasmo. Sábado = Saturday, por la mañana = in the morning — no se menciona.", 'fr': "A propose la séance de dimanche à 14 h, et B accepte avec enthousiasme. Samedi = Saturday, le matin = in the morning — non mentionné.", 'de': "A schlägt die Vorstellung am Sonntag um 14 Uhr vor, und B stimmt begeistert zu. Samstag = Saturday, vormittags = in the morning – nicht erwähnt."})),
      MockQuestion(id: "ja_n4_mock_q025", section: "listening", type: MockQuestionType.multiple_choice, question: "パソコンは どう なりましたか。", questionEn: "What happened to the computer?", correctAnswer: "がめんが まっくら", distractors: const ["おとが でない", "でんげんが はいらない", "こわれていない"], explanation: const LocalizedText({'en': "A says 画面が真っ暗なんです (the screen is completely dark). This is the direct symptom. The power turns on (電源を入れても = even when turning on), so it's not a power issue.", 'ko': "A 씨는 “화면이 완전히 검게 변했어요”라고 말합니다. 이것이 바로 직접적인 증상입니다. 전원은 켜지므로(전원을 켜도 = 전원을 켜도), 전원 문제는 아닙니다.", 'ja': "Aさんが「画面が真っ暗なんです」と言っています。電源は入るそうです。", 'zh': "A 说：“画面完全是黑的”。这是直接表现出的症状。电源可以打开（即使打开电源），所以这不是电源问题。", 'zh_TW': "A 說：「畫面完全是黑的」。這是直接的症狀。電源可以開啟（即使開啟電源），因此這不是電源問題。", 'es': "A dice: «La pantalla está completamente a oscuras». Este es el síntoma más evidente. El dispositivo se enciende (aunque se encienda = incluso al encenderlo), por lo que no se trata de un problema de alimentación.", 'fr': "A dit : « L'écran est complètement noir ». C'est le symptôme direct. L'appareil s'allume (même en le mettant sous tension), ce n'est donc pas un problème d'alimentation.", 'de': "A sagt: „Der Bildschirm ist komplett schwarz.“ Das ist das unmittelbare Symptom. Das Gerät lässt sich einschalten (auch wenn man den Strom einschaltet), es handelt sich also nicht um ein Problem mit der Stromversorgung."})),
    ],
  );
}
enum MockQuestionType { multiple_choice, fill_in_blank }
class MockTest { final String examName; final String language; final List<MockSection> sections; final List<MockQuestion> questions; const MockTest({required this.examName, required this.language, required this.sections, required this.questions}); }
class MockSection { final String sectionId; final String title; final int count; const MockSection({required this.sectionId, required this.title, required this.count}); }
class MockQuestion { final String id; final String section; final MockQuestionType type; final String question; final String questionEn; final String correctAnswer; final List<String> distractors; final LocalizedText explanation; const MockQuestion({required this.id, required this.section, required this.type, required this.question, required this.questionEn, required this.correctAnswer, required this.distractors, required this.explanation}); }
